INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2372', 'spa', 'Ver, contemplar, percibir; sinónimo poético de ra''ah, que abarca desde la visión física hasta la visión profética y la contemplación reverente.', 'Ver, contemplar, percibir; sinónimo poético de ra''ah, que abarca desde la visión física hasta la visión profética y la contemplación reverente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2373', 'spa', 'Pecho o pechuga de un animal sacrificial, designado como ofrenda mecida para los sacerdotes.', 'Término exclusivamente sacerdotal para la porción del pecho de un animal sacrificial que era ritualmente mecida ante el SEÑOR y luego entregada a los sacerdotes aarónicos como su porción asignada. Cada una de sus 13 apariciones se sitúa dentro de la legislación sacrificial — el carnero de consagración (Éxodo 29:26-27), la ofrenda de paz (Levítico 7:30-34) y el sacrificio del nazareo (Números 6:20). El español ''pecho'', el francés ''poitrine'' y el alemán ''Brust'' confirman el significado anatómico. La palabra traza la intersección entre la carnicería, la liturgia y la provisión sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2374', 'spa', 'Vidente o profeta visionario que recibe revelaciones divinas; raramente, un pacto o acuerdo de alianza', 'Vidente o profeta visionario que recibe revelaciones divinas; raramente, un pacto o acuerdo de alianza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2376', 'spa', 'Visión o revelación profética; apariencia externa (arameo, usado en Daniel)', 'Sustantivo arameo que aparece exclusivamente en Daniel. חֵזוּ (ḥezū) designa una visión concedida por Dios, especialmente las visiones nocturnas que estructuran los capítulos apocalípticos de Daniel. La frase ''visiones de mi cabeza sobre mi cama'' (Dn 4:5, 10; 7:1, 15) presenta estas revelaciones como algo percibido interiormente por la mente, no por los ojos. En un caso (Dn 7:20), el término pasa a denotar la apariencia física externa: el aspecto del cuerno pequeño cuya apariencia era ''mayor que la de sus compañeros''. Las traducciones árabes ruʾā, el coreano hwansang (환상) y el suajili maono coinciden en el sentido visionario, mientras que el único uso de ''apariencia'' se alinea con el cognado hebreo ḥāzōn en su acepción concreta más rara.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2377', 'spa', 'Visión — una revelación profética recibida en estado extático o visionario, o el oráculo profético en sí mismo', 'Visión — una revelación profética recibida en estado extático o visionario, o el oráculo profético en sí mismo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2380', 'spa', 'Visión, oráculo profético; también pacto o acuerdo (como algo ''visto'' o concertado con otra parte)', 'Emparentado con el verbo חָזָה (''ver, percibir''), este sustantivo designa una visión profética u oráculo y, por extensión, un acuerdo o pacto. Isaías lo emplea para una revelación divina severa (Is 21:2), una visión profética sellada e incomprensible para sus destinatarios (Is 29:11), y controversialmente para el ''pacto con el Seol'' de Judá (Is 28:18). En Daniel describe un rasgo conspicuo: el cuerno prominente del macho cabrío (Dn 8:5, 8). El español ''visión'' preserva el sentido profético nuclear, mientras que la traducción ''pacto'' en Is 28:18 refleja el significado secundario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2384', 'spa', 'Visión, revelación profética; una experiencia sobrenatural recibida en éxtasis o durante la noche, que transmite comunicación divina.', 'Este sustantivo designa una visión o experiencia reveladora, frecuentemente recibida de noche o en un estado de trance profético. Está estrechamente emparentado con el más común חָזוֹן, pero tiende a subrayar la cualidad vívida y visionaria de la experiencia. En 2 Samuel 7:17, Natán comunica la promesa de Dios a David «conforme a toda esta visión». Job emplea la palabra para las aterradoras visiones nocturnas que atormentan al sufriente (Job 4:13; 7:14; 33:15), mientras que Joel 3:1 promete que los jóvenes tendrán visiones en la era mesiánica. Zacarías 13:4 advierte que los falsos profetas se avergonzarán de sus visiones cuando Dios purifique la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2385', 'spa', 'Relámpago, rayo, destello de tormenta', 'Término poético que designa el relámpago o el rayo, enfatizando el destello brillante que acompaña al trueno. La palabra aparece exclusivamente en contextos poéticos que describen el dominio de Dios sobre los fenómenos meteorológicos. Job la emplea dos veces al contemplar la sabiduría divina en el gobierno del orden natural, mientras que Zacarías la utiliza en un oráculo profético sobre Dios enviando lluvia y tormentas. El término capta tanto el resplandor visual como la poderosa energía de la descarga eléctrica durante las tempestades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2386', 'spa', 'Cerdo o puerco, animal ritualmente impuro prohibido como alimento; también el jabalí que devasta la viña de Israel.', 'La palabra hebrea estándar para el cerdo doméstico, animal que ocupa un lugar singularmente repudiado en la ley israelita y la retórica profética. Levítico 11:7 y Deuteronomio 14:8 lo declaran impuro porque, aunque tiene pezuña hendida, no rumia. Isaías emplea la imagen del cerdo para condenar la apostasía: comer carne de cerdo en jardines secretos (65:4), ofrecer sangre de cerdo como sacrificio (66:3) y consumir puerco junto con otras abominaciones (66:17). Proverbios 11:22 ofrece el memorable símil del anillo de oro en el hocico de un cerdo. Una aparición en el Salmo 80:14 especifica al jabalí que arrasa la vid de Dios, metáfora de los enemigos de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2388', 'spa', 'Ser fuerte, firme; asir, agarrar; fortalecer, animar; reparar edificios; endurecer (corazón); prevalecer.', 'Con 290 ocurrencias, esta raíz se ancla en la firmeza y la fuerza pero irradia hacia el asimiento físico, el fortalecimiento emocional, la reparación estructural y el endurecimiento moral. El Qal cubre la fuerza inherente (''¡sé fuerte!''), el Hifil añade el gesto intencional de agarrar (''la tomó de la mano''), el Piel intensifica hacia fortalecer a otros o endurecer el corazón de Faraón, y el Hitpael se vuelve reflexivo (''se fortaleció''). Lo fascinante de este verbo es cómo las lenguas reparten su carga semántica: el árabe usa raíces distintas para ''ser fuerte'' (قَوِيَ), ''asir'' (أَمْسَكَ), ''reparar'' (رَمَّمَ) y ''endurecer'' (قَسَّى), mientras que el hebreo lo unifica todo bajo el concepto único de firmeza —ya sea de manos, corazones, muros o voluntades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2389', 'spa', 'Fuerte, poderoso, potente; también severo o feroz en intensidad; duro o inflexible de carácter; con fuerza (uso adverbial).', 'Fuerte, poderoso, potente; también severo o feroz en intensidad; duro o inflexible de carácter; con fuerza (uso adverbial).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2392', 'spa', 'Fuerza, poder; usado para el poder divino (la mano fuerte de Dios) y para la fuerza militar nacional', 'Este sustantivo denota fuerza o poder y aparece en dos ámbitos distintos. Tres veces en Éxodo (13:3, 14, 16) describe la ''fuerza de mano'' de Dios que sacó a Israel de Egipto, una expresión formulaica que ancla la memoria israelita del Éxodo. En Amós 6:13 y Hageo 2:22 se refiere a la fuerza militar humana: la jactancia desmedida de Israel y el derrocamiento de los carros de guerra de los reinos. El francés ''force'' y el alemán ''Stärke'' transmiten consistentemente poder crudo, mientras que el español ''fuerza'' cubre tanto la aplicación divina como la militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2393', 'spa', 'Fuerza, vigor, poderío; la fortaleza asociada a la compulsión profética o al poder real consolidado.', 'Sustantivo que expresa una fuerza imperiosa, derivado de la raíz verbal חזק (''ser fuerte''). En las Escrituras presenta dos matices diferenciados: la compulsión irresistible de la mano de Dios sobre un profeta y el poderío consolidado de un rey en el apogeo de su reinado. En Isaías 8:11, el Señor agarra al profeta בְּחֶזְקַת הַיָּד —con mano fuerte— advirtiéndole que no siga el temor del pueblo. En Crónicas y Daniel, describe el momento en que el poder de un rey queda plenamente afianzado, a menudo justo antes de un giro fatal hacia la soberbia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2394', 'spa', 'fuerza, violencia; (como infinitivo) reforzar, reparar', 'Sustantivo femenino que denota fuerza o violencia, casi siempre en la frase preposicional fija be-chozqah, ''con fuerza''. Describe el tipo de poder que coacciona y oprime: Jabín aplastando a Israel ''con fuerza'' (Jue 4:3), los sacerdotes arrebatando la carne ''por la fuerza'' (1 Sam 2:16), pastores gobernando ''con dureza'' (Ez 34:4). Sin embargo, en Jon 3:8 la misma frase describe clamar a Dios ''con intensidad'', mostrando que la fuerza bruta puede servir tanto a la crueldad como al arrepentimiento. Una aparición en 2 Re 12:12 es en realidad un infinitivo del verbo חָזַק, que significa ''reparar'' el Templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2396', 'spa', 'Ezequías — nombre propio que significa ''YHWH ha fortalecido''; principalmente el rey justo de Judá (c. 715-686 a. C.).', 'חִזְקִיָּהוּ (también escrito חִזְקִיָּה, יְחִזְקִיָּהוּ) es un nombre teofórico construido a partir de חָזַק (''ser fuerte'') y un sufijo divino, con el significado ''YHWH ha fortalecido''. De sus 130 ocurrencias, la gran mayoría designan al rey de Judá que sucedió a su idólatra padre Acaz e instituyó amplias reformas religiosas (2 R 18:3-6). Su reinado es recordado por la milagrosa liberación de Jerusalén del asedio de Senaquerib (2 R 19:35; Is 37:36) y la señal del retroceso de la sombra del reloj solar durante su enfermedad (2 R 20:11). Proverbios 25:1 atribuye una colección escribal a ''los varones de Ezequías''. Los anales asirios lo confirman como Hazakiiahu, un caso excepcional de coincidencia entre un nombre bíblico y su registro cuneiforme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2397', 'spa', 'Garfio o anillo para sujetar cautivos y animales; también un broche o prendedor ornamental ofrendado para el tabernáculo.', 'El sustantivo חַח designa un aro o garfio metálico, pero su significado se bifurca drásticamente entre dos mundos. En su acepción dominante, es un instrumento de sometimiento: un gancho clavado en la nariz o la mandíbula de un cautivo para arrastrarlo como a un animal. Dios advierte a Senaquerib: «Pondré mi garfio en tu nariz» (2 R 19:28; Is 37:29), y Ezequiel retrata a los príncipes de Judá como leones jóvenes arrastrados con garfios (Ez 19:4, 9). En su única otra aparición, la misma palabra designa un delicado broche ornamental llevado como ofrenda voluntaria para el Tabernáculo (Éx 35:22), un recordatorio llamativo de que la metalurgia antigua servía tanto a la crueldad como a la belleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2398', 'spa', 'Pecar, errar el blanco, purificar del pecado; falta moral (Qal), hacer pecar (Hifil), purificación ritual (Piel/Hitpael).', 'El verbo חָטָא (240 ocurrencias) se centra en el concepto de errar un objetivo o norma, comúnmente la transgresión moral. El Qal (165x) denota cometer pecado contra Dios o la ley ética, mientras que el Hifil causativo (32x) significa inducir a otro a pecar. El Piel (14x) y el Hitpael (9x) invierten por completo la polaridad semántica, expresando purificación ritual del pecado: ofrecer un sacrificio expiatorio, purificar el altar o someterse a limpieza ceremonial. El participio Qal se divide en el sustantivo ''pecador'' (9x) y el verbal ''pecando'' (8x) según el contexto sintáctico. Cognados en árabe, coreano y suajili conservan el sentido moral en Qal/Hifil y el de purificación en Piel/Hitpael, confirmando patrones polisémicos estables dentro del sistema verbal semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2399', 'spa', 'Pecado, transgresión contra Dios o el prójimo; raramente ofrenda por el pecado o falta menor', 'Pecado, transgresión contra Dios o el prójimo; raramente ofrenda por el pecado o falta menor');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2400', 'spa', 'Pecaminoso; pecadores — aquellos caracterizados por el pecado, usado tanto como sustantivo como adjetivo atributivo. Chattá'' identifica a personas def', 'Pecaminoso; pecadores — aquellos caracterizados por el pecado, usado tanto como sustantivo como adjetivo atributivo. Chattá'' identifica a personas definidas por su pecado. En su uso más común funciona como sustantivo que significa ''pecadores'': aquellos que se oponen a los justos, como en la apertura del Salterio: ''Bienaventurado el que no anda en consejo de malos ni se detiene en camino de pecadores'' (Sal 1:1). El término abarca desde Génesis 13:13, donde los hombres de Sodoma son ''pecadores contra Jehová en gran manera'', hasta los oráculos de Isaías contra los pecadores en Sion (Is 1:28; 33:14). En un uso singular y llamativo (Am 9:8), funciona como verdadero adjetivo que modifica ''reino'': el reino pecador destinado al juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2401', 'spa', 'Pecado, transgresión — una grave ofensa moral ante Dios; en raras ocasiones, una ofrenda por el pecado presentada en el altar.', 'El sustantivo femenino חֲטָאָה es una variante del más común חַטָּאת, y designa el pecado como una realidad moral de gran peso. Aparece casi exclusivamente en la frase חֲטָאָה גְדֹלָה («gran pecado»), señalando actos de gravedad extraordinaria: la casi violación de Sara por Abimelec (Gn 20:9), el becerro de oro (Éx 32:21, 30, 31) y la idolatría de Jeroboam (2 R 17:21). Los Salmos añaden profundidad teológica: el pecado puede ser «cubierto» en el perdón (Sal 32:1) y hasta la oración del malvado puede «convertirse en pecado» (Sal 109:7). Una única aparición en Sal 40:6 podría designar una ofrenda por el pecado, vinculando la falta moral con su remedio ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2402', 'spa', 'ofrenda por el pecado (cognado arameo del hebreo חַטָּאת)', 'Este término arameo aparece en Esdras 6:17, donde los exiliados que regresaron ofrecen sacrificios en la dedicación del templo reconstruido. La palabra es el equivalente arameo del hebreo חַטָּאת (ofrenda por el pecado), lo que refleja el carácter bilingüe de Esdras-Nehemías. El Ketiv lee חַטָּיָא mientras que el Qeré ofrece חַטָּאָה; ambas formas funcionan como préstamos del vocabulario sacrificial que trasciende las fronteras lingüísticas en los contextos litúrgicos del Segundo Templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2403b', 'spa', 'Pecado u ofrenda por el pecado — el acto de fallar ante Dios y el sacrificio prescrito para expiarlo.', 'Quizá el sustantivo de mayor carga teológica del vocabulario levítico, חַטָּאת porta dos significados íntimamente conectados: el pecado mismo y la ofrenda que lo remedia. Esta doble función no es accidental: codifica la lógica bíblica de que el remedio lleva el nombre de la enfermedad. El sentido de ofrenda por el pecado domina Levítico y Números, donde el francés ''offrande pour le péché'' y el alemán ''Sündopfer'' explicitan el significado sacrificial, mientras que el sentido de pecado impregna la literatura narrativa y profética, donde el español ''pecado'' y el francés ''péché'' se sostienen sin calificadores sacrificiales. Ambos sentidos comparten más de 40 versículos solo en Levítico 4, apareciendo a veces con ambas acepciones en un mismo versículo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2404', 'spa', 'Cortar o recoger leña, especialmente para combustible; en voz pasiva, ser tallado o esculpido.', 'Un verbo práctico arraigado en la labor cotidiana de cortar leña, que aparece con mayor frecuencia en la frase «cortadores de leña y aguadores», expresión que define el servicio más humilde (Jos 9:21, 23, 27; Dt 29:11). El árabe ḥaṭab (leña) y el etiópico ḥaṭaba (recoger leña) confirman el estrecho vínculo semántico con la recolección de combustible. Deuteronomio 19:5 ofrece la imagen más concreta: un hombre entra al bosque con su vecino a cortar leña y la cabeza del hacha sale volando. Una única aparición en Pual (Sal 144:12) desplaza el significado por completo, describiendo a las hijas «esculpidas» como columnas de un palacio: la misma raíz aplicada ya no a leña tosca, sino a escultura fina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2406', 'spa', 'Trigo — el cereal básico del antiguo Israel, cultivado como cultivo alimenticio principal y mercancía comercial', 'Trigo — el cereal básico del antiguo Israel, cultivado como cultivo alimenticio principal y mercancía comercial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2407', 'spa', 'Hatús; nombre postexílico portado por un descendiente davídico, un constructor del muro y un líder sacerdotal', 'Nombre propio que aparece en los registros genealógicos y administrativos del período postexílico. Hatús se asocia con al menos dos o tres individuos distintos. Uno pertenece a la línea real davídica (1 Cr 3:22; Esd 8:2), otro participó en la reconstrucción de la muralla de Jerusalén bajo Nehemías (Neh 3:10), y un tercero encabezaba una familia sacerdotal (Neh 10:4; 12:2). La Septuaginta lo transcribe de diversas formas como Χαττους y Αττους, y el paralelo nabateo Chatishu sugiere un uso semítico más amplio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2414', 'spa', 'Atrapar, arrebatar, agarrar repentinamente', 'Este verbo describe la acción súbita y enérgica de atrapar o arrebatar algo, a menudo con connotaciones depredadoras o violentas. Aparece tanto en contextos literales (apoderarse de esposas, como en Jueces 21:21) como figurados (el opresor atrapando al afligido como presa, en el Salmo 10:9). La acción es típicamente veloz y agresiva, implicando el sometimiento del objeto apresado. El verbo transmite un sentido de apropiación violenta, no de una toma apacible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2416a', 'spa', 'Vivo, viviente; que tiene vida; sustantivado: ser viviente; en fórmulas de juramento ''¡vive X!''; también crudo, fresco.', 'חַי es el adjetivo primario del hebreo bíblico para el estado de estar vivo, y desde ese núcleo biológico se proyecta hacia la teología, la liturgia, la zoología e incluso la alimentación. Como atributo divino, porta una fuerza enorme: el ''Dios vivo'' (אֵל חַי, Jos 3:10; Sal 42:3) no es un ídolo muerto sino la fuente de toda vitalidad. Sustantivado, designa criaturas vivientes — toda carne que respira (Gn 6:19). En la fórmula de juramento חַי יהוה (''¡vive el SEÑOR!''), se convierte en la garantía solemne más firme, anclada en la vida inextinguible de Dios mismo, con más de ochenta apariciones desde Jueces hasta Reyes. La palabra se extiende incluso a la frescura física: carne cruda (1 S 2:15) y piel viva (Lv 13:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2416c', 'spa', 'Ser viviente, bestia salvaje, animal; también las ''criaturas vivientes'' visionarias de Ezequiel; abstractamente ''vida'' o ''vitalidad''.', 'Este sustantivo femenino hebreo חַיָּה abarca todo el espectro desde la fauna silvestre ordinaria hasta las sobrecogedoras criaturas vivientes de la visión profética. En su uso más frecuente designa animales salvajes — ''la bestia del campo'' o ''la bestia de la tierra'' (Gn 1:25; 3:1). Sin embargo, en las visiones del trono de Ezequiel (Ez 1:5, 13-14), la misma palabra describe a los cuatro seres sobrenaturales. Con sufijos posesivos, חַיָּה también puede significar ''vida'' o ''vitalidad'' (Job 33:18-28), donde el árabe cambia a حَيَاة, revelando un sentido abstracto que la forma hebrea deja ambiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2416d', 'spa', 'Banda, tropa o comunidad; un grupo de familias aliadas o un rebaño asentado, distinto de חַיָּה (''criatura viviente'').', 'Sustantivo femenino poco frecuente, distinto del común חַיָּה (''criatura viviente''), que designa una banda, tropa o comunidad —un grupo de personas o criaturas que funcionan como unidad social. En 2 Samuel 23:13, una tropa de filisteos acampa en el valle de Refaím como partida de saqueo de familias aliadas. El Salmo 68:10 lo emplea para referirse al rebaño o congregación de Dios que habita en la tierra que él preparó para los pobres. Las traducciones reflejan una interesante variación interpretativa entre banda militar y comunidad asentada bajo el cuidado divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2416e', 'spa', 'Vida, duración de vida, existencia; el estado abstracto de estar vivo; sustantivado: ''los vivientes''.', 'Sustantivo plural enfático (חַיִּים) que expresa todo el peso de ''vida'' en hebreo — no meramente la existencia biológica sino la textura completa de los días de una persona. Aparece en el fundacional ''aliento de vida'' de Génesis 2:7, en el grito angustiado de Job (''¿por qué se da luz al de vida amarga?'', Job 3:20) y en la alabanza del salmista a Dios que ''mantiene nuestra alma entre los vivientes'' (Sal 66:9). La cadena constructa ''años de la vida de'' estructura las narrativas patriarcales (Gn 23:1; 25:7; 47:8-9). Ocasionalmente la forma pasa de lo abstracto a lo concreto, refiriéndose a ''los vivientes'' como grupo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2417', 'spa', 'Adjetivo arameo ''viviente, vivo'' usado como epíteto divino y sustantivado; también sustantivo que significa ''vida''.', 'Palabra aramea que aparece exclusivamente en Daniel y Esdras, con dos usos estrechamente relacionados pero gramaticalmente distintos. Como adjetivo describe a Dios como ''el Viviente'' (Daniel 6:20, 26) y a las personas como ''los vivientes'' (Daniel 4:17), haciendo eco del hebreo חַי. Como sustantivo significa ''vida'' o ''tiempo de vida'', como cuando los judíos oran ''por la vida del rey'' (Esdras 6:10). Las traducciones al español viviente y los-vivientes conservan bien la fuerza sustantiva de este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2418', 'spa', 'vivir, estar vivo (arameo); (Hafel) dejar vivir, preservar la vida', 'Verbo arameo que significa ''vivir'', conocido principalmente por el saludo cortesano formulaico ''¡Oh rey, vive para siempre!'' (Dan 2:4; 3:9; 5:10; 6:6, 21). Este deseo de deferencia aparece en labios de astrólogos, reinas y funcionarios por igual, convirtiéndolo en la fórmula aramea estándar ante la realeza. En su única aparición en Hafel (Dan 5:19), el verbo adquiere fuerza causativa: Nabucodonosor tenía el poder de ''dejar vivir'' a quien él quisiese. El español ''dejaba vivir'' capta con precisión esta prerrogativa real de vida y muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2420', 'spa', 'Enigma, dicho enigmático — expresión oscura o desconcertante que requiere interpretación, incluyendo alegorías y proverbios. Chidah designa un enigma ', 'Enigma, dicho enigmático — expresión oscura o desconcertante que requiere interpretación, incluyendo alegorías y proverbios. Chidah designa un enigma o dicho enigmático que exige esfuerzo interpretativo del oyente. Conocido sobre todo por el acertijo de Sansón en Jueces 14, donde aparece siete veces cuando desafía a los filisteos con un dicho oscuro nacido de experiencia personal (Jue 14:12-19), el término va mucho más allá de juegos de salón. En Números 12:8, Dios distingue a Moisés de otros profetas diciendo que habla con él ''boca a boca, claramente, y no en enigmas'', ubicando a chidah en el extremo oscuro del espectro de revelación. La reina de Sabá prueba a Salomón ''con enigmas'' (1 R 10:1; 2 Cr 9:1). Proverbios 1:6 agrupa chidot junto a mashal (''proverbio'') y melitsah (''figura''). Ezequiel 17:2 recibe orden de ''proponer un enigma y hablar una alegoría'', y Habacuc 2:6 aplica el término a oráculos de burla contra Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2421', 'spa', 'Vivir, estar vivo; revivir, dar vida; mantener con vida, perdonar la vida; sanar de enfermedad.', 'El verbo hebreo fundamental de la vitalidad y la fuerza vital, que recorre todo el arco desde la mera supervivencia hasta la resurrección milagrosa. En su conjugación Qal describe el estado ordinario de estar vivo (Gn 5:3ss, el genealógico ''y vivió''), mientras que sus formas Piel e Hifil avanzan hacia territorio causativo — resucitar a los muertos (1 S 2:6), preservar a los vivos (Gn 6:19-20) y sanar a los enfermos (2 R 20:7). El árabe distribuye estas acepciones entre raíces distintas — عَاشَ para vivir, أَحْيَا para revivir, شَفَى para sanar — mientras que el hebreo las reúne en un solo verbo, subrayando la convicción bíblica de que toda vida procede de una sola fuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2423', 'spa', 'Bestia, animal (arameo) — usado en Daniel para bestias literales y criaturas apocalípticas. El equivalente arameo del hebreo חַיָּה, este sustantivo a', 'Bestia, animal (arameo) — usado en Daniel para bestias literales y criaturas apocalípticas. El equivalente arameo del hebreo חַיָּה, este sustantivo aparece exclusivamente en el libro de Daniel, donde tiene fuerza tanto literal como visionaria. En las secciones narrativas designa animales salvajes del campo hacia los cuales Nabucodonosor fue echado (Dan 4:12-23; 5:21). En las visiones apocalípticas del capítulo 7, describe las cuatro grandes bestias que suben del mar — criaturas compuestas que simbolizan imperios sucesivos (Dan 7:3-23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2425', 'spa', 'Vivir, estar vivo, permanecer con vida — el verbo hebreo básico para poseer o sostener la vida. El verbo hebreo fundamental para estar vivo y continua', 'Vivir, estar vivo, permanecer con vida — el verbo hebreo básico para poseer o sostener la vida. El verbo hebreo fundamental para estar vivo y continuar viviendo. Su rango semántico se extiende desde la mera existencia biológica hasta la promesa teológica de la vida como don divino. Dios advierte a Moisés que nadie puede ver su rostro y vivir (Éx 33:20); el árbol de la vida permitiría a la humanidad vivir para siempre (Gn 3:22); los resúmenes patriarcales registran cuánto vivió cada figura (Gn 5:5; 25:7). En contextos proféticos, Jeremías promete que quienes se rindan a Babilonia ''vivirán'' (Jer 21:9; 38:2) — supervivencia como misericordia del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2426', 'spa', 'Ejército o fuerza militar; muralla, fortificación o baluarte de una ciudad; fuerza, poder o vigor. Chel lleva una doble vida marcial: nombra tanto al ', 'Ejército o fuerza militar; muralla, fortificación o baluarte de una ciudad; fuerza, poder o vigor. Chel lleva una doble vida marcial: nombra tanto al ejército que asedia una ciudad como a la muralla que la defiende. Como término militar (11 apariciones), surge en relatos donde Tou envía a su hijo a David ''con su ejército'' (2 Sam 8:9; 1 Cr 18:9) y el ejército sirio viene contra Judá (2 Cr 24:23). Como término de fortificación (6 apariciones), designa la muralla exterior o baluarte: ''Extendió cordel sobre la muralla y el muro'' en el lamento por Jerusalén (Lam 2:8), y el salmista bendice a Sion con ''paz dentro de tus muros'' (Sal 122:7). Un sentido residual de ''fuerza'' bruta une ambos, como en el envío de la ''fuerza'' del ejército (1 Cr 20:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2427a', 'spa', 'Dolor convulsivo, angustia o dolores de parto — sufrimiento físico o emocional intenso comparado con el trabajo de parto.', 'Sustantivo que denota dolor agudo y convulsivo, ya sean las contorsiones físicas del miedo o la angustia del parto. Su uso más vívido compara el terror militar o nacional con los dolores de una mujer en trabajo de parto (Sal 48:6; Miq 4:9; Jer 6:24; 50:43). En Éx 15:14, describe el terror estremecedor que se apoderó de las naciones ante la noticia de la liberación de Israel. La metáfora del parto recurre con tanta constancia que la palabra casi siempre evoca la imagen del alumbramiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2428', 'spa', 'Ejército, fuerza militar; valor, valentía; riqueza, bienes; fuerza, poder; capacidad, competencia, virtud.', 'Uno de los sustantivos más versátiles de la Biblia hebrea, חַיִל irradia desde una idea nuclear de capacidad vigorosa. Nombra al ejército que Faraón pierde en el mar (Éx 14:28), el valor heroico del גִּבּוֹר חַיִל (guerrero valeroso, Jue 6:12), la riqueza material que Dios da poder para producir (Dt 8:18) y la excelencia moral de la אֵשֶׁת חַיִל, la ''mujer virtuosa'' de Proverbios 31:10. El árabe separa estos sentidos nítidamente — جيش para ejército, شجاعة para valor, ثروة para riqueza, قوة para fuerza — confirmando que lo que el hebreo mantiene unido en un solo lexema, otras lenguas lo distinguen. El hilo teológico es que todo חַיִל genuino, sea militar, económico o moral, procede en última instancia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2429', 'spa', 'Sustantivo arameo que significa ''poder, fuerza''; también ''ejército, hueste militar'', cognado arameo del hebreo חַיִל.', 'Este sustantivo arameo aparece en Esdras y Daniel, abarcando el mismo amplio campo semántico que su cognado hebreo חַיִל. Denota poder físico o político, como en Esdras 4:23 donde los adversarios detienen la reconstrucción de Jerusalén ''con fuerza y poder''. También se extiende a una fuerza o ejército militar, como cuando los poderosos soldados de Nabucodonosor son llamados גִּבָּרֵי חַיִל (Daniel 3:20). El español fuerza traduce consistentemente la acepción de ''poder'', mientras que ejército distingue la aplicación militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2435', 'spa', 'exterior, externo — describe lo que está fuera, especialmente los atrios y puertas exteriores del templo', 'exterior, externo — describe lo que está fuera, especialmente los atrios y puertas exteriores del templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2436', 'spa', 'Seno, regazo o abrazo (del cuerpo o del pliegue del vestido); también la base o repisa inferior de una estructura de altar', 'Seno, regazo o abrazo (del cuerpo o del pliegue del vestido); también la base o repisa inferior de una estructura de altar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2438', 'spa', 'Hiram — rey de Tiro aliado de David y Salomón; también un maestro artesano; también un benjaminita', 'Hiram — rey de Tiro aliado de David y Salomón; también un maestro artesano; también un benjaminita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2441', 'spa', 'Paladar, cielo de la boca; el órgano del gusto usado literal y metafóricamente; también boca como órgano del habla. Designa el cielo de la boca — el p', 'Paladar, cielo de la boca; el órgano del gusto usado literal y metafóricamente; también boca como órgano del habla. Designa el cielo de la boca — el paladar físico donde se disciernen los sabores. Job pregunta ''¿no distingue el paladar la comida?'' (Job 12:11), y Proverbios compara la dulzura de la sabiduría con la miel en el paladar (Pr 24:13). La palabra es predominantemente poética, concentrada en Job, Proverbios, Cantar de los Cantares y los Salmos. Un uso metonímico secundario trata al paladar como fuente del habla: ''su paladar es dulcísimo'' (Cnt 5:16), y la lengua del profeta pegada a su paladar señala silencio forzado (Ez 3:26).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2442', 'spa', 'Esperar con expectación, a menudo con esperanza; raramente, acechar con intención hostil.', 'Un verbo de expectación paciente, típicamente dirigido hacia Dios o su liberación. La forma intensiva Pi''el subraya la cualidad deliberada y sostenida de esta espera — no es pasividad ociosa sino anticipación activa y esperanzada. Isaías lo usa para quienes esperan en el Señor (Isaías 8:17; 30:18), y el salmista declara que ''nuestra alma espera en el SEÑOR'' (Salmo 33:20). Un caso notable en Oseas 6:9 reutiliza el mismo verbo para la emboscada depredadora, donde los sacerdotes ''acechan'' como bandas de salteadores — una inversión oscura de su tono habitualmente esperanzado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2443', 'spa', 'Anzuelo, gancho para pescar o capturar grandes criaturas', 'Un anzuelo empleado para la pesca o la captura de grandes criaturas acuáticas. El término aparece en contextos que van desde la pesca ordinaria hasta la captura metafórica del Leviatán. Isaías describe a los pescadores echando anzuelos en el Nilo, mientras que Habacuc utiliza la imagen de la humanidad atrapada como peces con anzuelos. De manera más dramática, Job pregunta si el Leviatán puede ser sacado con un anzuelo, subrayando el poder indomable de la criatura. El anzuelo representa los intentos humanos de controlar la vida acuática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2444', 'spa', 'Haquilá: colina en el sur de Judá cerca del desierto de Zif', 'Una colina situada en el sur de Judá, al borde del desierto de Zif. Haquilá sirvió como punto de referencia durante los años de David como fugitivo, cuando Saúl lo perseguía. Los zifeos informaron dos veces a Saúl de que David se escondía cerca de la colina de Haquilá, lo que desencadenó enfrentamientos entre ambos. El nombre posiblemente significa «oscura» o «sombría», quizás describiendo el aspecto de la colina. Este lugar marca un capítulo significativo en las andanzas de David antes de ser rey por el desierto de Judea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2445', 'spa', 'Sabios, eruditos — término arameo para la clase letrada en la corte babilónica poseedora de conocimiento esotérico.', 'Un sustantivo arameo (חַכִּים) que aparece exclusivamente en Daniel, designando la clase profesional de sabios o eruditos en las cortes babilónica y persa. Estos חַכִּימִין aparecen junto a magos, encantadores y astrólogos como consejeros de la corte a quienes Nabucodonosor y Belsasar consultan para la interpretación de sueños y la lectura de signos crípticos. Cuando Dios revela el sueño de Nabucodonosor a Daniel, se dice que Dios ''da sabiduría a los sabios'' (Daniel 2:21), usando la misma raíz. El inglés y el español rinden el término directamente como ''wise men'' y ''sabios''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2449', 'spa', 'Ser sabio, volverse sabio, actuar sabiamente; en las formas causativas, hacer sabio o enseñar sabiduría; reflexivamente, mostrarse sabio', 'Ser sabio, volverse sabio, actuar sabiamente; en las formas causativas, hacer sabio o enseñar sabiduría; reflexivamente, mostrarse sabio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2450', 'spa', 'Sabio, prudente; sustantivado: sabios, consejeros reales; también artesano diestro; femenino: mujeres sabias.', 'חָכָם es el adjetivo primario del hebreo bíblico para la sabiduría en todas sus dimensiones — moral, intelectual y práctica. En su uso más común describe a quien posee discernimiento y prudencia: Moisés recibe la orden de elegir hombres ''sabios y entendidos'' (Dt 1:13), y el sabio teme al SEÑOR y se aparta del mal (Pr 14:16). Pero חָכָם funciona también como sustantivo que designa una clase social reconocida — los ''sabios'' que sirven como consejeros reales junto a sacerdotes y profetas (Jer 18:18), desde los magos de la corte de Faraón (Éx 7:11) hasta los consejeros de Babilonia y Persia. Un tercer sentido, a menudo pasado por alto, emerge en las narraciones del tabernáculo: artesanos cuyo corazón Dios llenó de ''sabiduría'' para trabajar el oro, tejer telas y tallar madera (Éx 28:3; 35:25). El femenino plural en Jueces 5:29 y Jeremías 9:17 designa a las mujeres sabias como categoría social propia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2451', 'spa', 'Sabiduría, discernimiento, buen juicio; habilidad técnica o artesanal; consejo prudente.', 'Abarcando desde la pericia artesanal hasta la omnisciencia divina, חָכְמָה es el término hebreo más amplio para la inteligencia aplicada. Sus primeras apariciones en Éxodo describen la habilidad dada por Dios a los artesanos del tabernáculo — Bezalel lleno de חָכְמָה para trabajar en oro, plata y bronce (Éx 31:3; 35:31). La חָכְמָה de Salomón sobrepasó célebremente toda la sabiduría de Egipto y del Oriente (1 R 4:30), abarcando en un solo trazo la botánica, la zoología, la perspicacia judicial y la administración política. En Proverbios, la Sabiduría personificada se alza en las encrucijadas llamando a los transeúntes (Pr 1:20; 8:1; 9:1), y ''el temor del SEÑOR'' se declara su punto de partida (Pr 9:10). Eclesiastés somete el concepto a un escrutinio implacable, preguntando si toda esta חָכְמָה aprovecha realmente bajo el sol (Ecl 1:13-18; 2:13-16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2452', 'spa', 'Sabiduría (arameo); discernimiento otorgado por Dios, capacidad interpretativa y comprensión integral, especialmente en Daniel.', 'Esta es la forma aramea de «sabiduría», que aparece exclusivamente en Daniel y Esdras. En Daniel, la sabiduría es primero un atributo de Dios mismo — «suyos son la sabiduría y el poder» (Dn 2:20) — y luego un don que él concede a quienes le buscan (2:21, 23). Daniel atribuye a Dios la capacidad interpretativa que ninguno de los sabios de Babilonia pudo ofrecer (2:30). En Daniel 5:11, 14, la reina madre testimonia que «la sabiduría de los dioses» reside en Daniel. Esdras 7:25 emplea el término de forma práctica: Esdras recibe el encargo de nombrar jueces «conforme a la sabiduría de tu Dios».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2454', 'spa', 'Sabiduría; destreza, discernimiento y sagacidad que abarca oficio técnico, gobierno, ética y orden cósmico', 'Uno de los términos teológicamente más ricos de la Biblia hebrea, este sustantivo cubre un espectro extraordinario que va desde la habilidad artesanal hasta el principio cósmico. En Proverbios, la Sabiduría personificada clama en las calles (1:20), edifica su casa con siete columnas (9:1) y queda fuera del alcance del necio (24:7). La forma plural en Prov 14:1 (''las sabidurías de las mujeres'') subraya el carácter múltiple y práctico de la verdadera sabiduría. El español ''sabiduría'', el francés ''sagesse'' y el alemán ''Weisheit'' convergen en un solo concepto que une discernimiento moral con destreza práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2455', 'spa', 'Profano, común u ordinario — lo que no está consagrado; lo opuesto a lo santo (קֹדֶשׁ).', 'Sustantivo que marca la frontera entre lo sagrado y lo ordinario. En la ley sacerdotal, distinguir entre lo santo (קֹדֶשׁ) y lo común (חֹל) es un deber fundamental de los sacerdotes (Lv 10:10; Ez 44:23). Ezequiel condena a los sacerdotes de Jerusalén por no enseñar esta distinción (22:26) y emplea el término arquitectónicamente cuando el recinto del templo separa el espacio santo del terreno común (42:20; 48:15). La petición de David de ''pan común'' en Nob (1 S 21:5-6) — panes ordinarios en contraste con el pan consagrado de la proposición — ofrece una memorable ilustración narrativa de esta división entre lo sacro y lo secular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2457', 'spa', 'Herrumbre, corrosión; escoria o inmundicia en un recipiente metálico, símbolo de la impureza moral de Jerusalén', 'Este sustantivo, que aparece exclusivamente en Ezequiel 24:6-12, describe la herrumbre o corrosión incrustada en una olla de cocina, la vívida alegoría de Ezequiel sobre la culpa de sangre y la inmundicia moral de Jerusalén. La olla no puede limpiarse; su herrumbre debe ser consumida por el fuego del juicio divino. El término probablemente se relaciona con una raíz que significa ''estar enfermo'' o ''ser inmundo'', conectando la corrosión física con la contaminación espiritual. El español ''escoria'' y el francés ''rouille'' captan la imagen de una corrupción irreversible que solo el fuego puede abordar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2459', 'spa', 'Grasa, sebo — las porciones grasas de los animales sacrificiales; en sentido figurado, lo mejor o más selecto de algo.', 'Grasa, sebo — las porciones grasas de los animales sacrificiales; en sentido figurado, lo mejor o más selecto de algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2461', 'spa', 'Leche; por extensión queso o cuajada; metonímicamente un lactante; también un nombre propio (Juram)', 'Leche; por extensión queso o cuajada; metonímicamente un lactante; también un nombre propio (Juram)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2465', 'spa', 'Duración de la vida, existencia transitoria; el mundo visto como el lapso de la existencia humana', 'El hebreo חֶלֶד transmite la fugaz duración de la vida mortal, en paralelo cercano con el griego αἰών en su sentido temporal. En Job 11:17 describe una vida que podría brillar más que el mediodía, mientras que el Salmo 39:5 lo empareja con ''mis días'' en una conmovedora meditación sobre la brevedad. El Salmo 49:1 extiende el significado hacia ''mundo'' como esfera colectiva de la transitoriedad humana, convocando a todos los habitantes de חֶלֶד a escuchar. El español ''duración'' y ''mundo'' captan conjuntamente tanto la vida personal como el ámbito temporal más amplio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2470a', 'spa', 'estar enfermo, enfermar; debilitarse, decaer; ser grave (de heridas); hacer enfermar, causar enfermedad; fingir enfermedad; afligirse, sufrir dolor; s', 'estar enfermo, enfermar; debilitarse, decaer; ser grave (de heridas); hacer enfermar, causar enfermedad; fingir enfermedad; afligirse, sufrir dolor; ser herido (pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2470b', 'spa', 'Suplicar, buscar favor, apaciguar — implorar fervientemente la respuesta graciosa de alguien, especialmente la de Dios. Verbo Piel derivado de una raí', 'Suplicar, buscar favor, apaciguar — implorar fervientemente la respuesta graciosa de alguien, especialmente la de Dios. Verbo Piel derivado de una raíz que significa ''ser dulce o agradable'', usado exclusivamente con la expresión ''hacer dulce el rostro de [alguien]'', es decir, aplacar, apaciguar o buscar fervientemente el favor de alguien. Casi siempre dirigido a Dios, aparece en momentos cruciales de intercesión: Moisés suplica a YHWH después del becerro de oro (Éx 32:11), Samuel es presionado por Saúl en Gilgal (1 Sam 13:12), y el varón de Dios ruega por la mano marchita de Jeroboam (1 R 13:6). Daniel confiesa que Israel no suplicó el favor del Señor (Dan 9:13), y Malaquías irónicamente ordena a los sacerdotes ''suplicar el favor de Dios'' cuando sus ofrendas carecen de valor (Mal 1:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2471', 'spa', 'Una torta perforada o pan en forma de anillo usado en las ofrendas de cereal y comidas rituales israelitas.', 'Un sustantivo femenino que designa un tipo específico de ofrenda horneada — probablemente una torta perforada o en forma de anillo, ya que el nombre puede derivar de la raíz que significa ''perforar''. Las 14 apariciones se dan en contextos rituales dentro del Pentateuco. Estas tortas se preparan de diversas maneras: sin levadura y mezcladas con aceite para la ofrenda de cereal (Levítico 2:4; 7:12), horneadas con flor de harina para el pan de la Presencia (Levítico 24:5), ofrecidas como primicias de la masa (Números 15:20), o incluidas en la consagración de sacerdotes (Éxodo 29:2, 23; Levítico 8:26). El español usa ''torta'' consistentemente, mientras que el inglés rinde el término como ''cake''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2472', 'spa', 'חֲלוֹם — un sueño; una visión nocturna, a menudo con significado profético o revelador.', 'חֲלוֹם — un sueño; una visión nocturna, a menudo con significado profético o revelador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2473', 'spa', 'Holón: ciudad en la serranía de Judá asignada a los levitas, y ciudad en Moab mencionada en el oráculo de Jeremías', 'Nombre de lugar que aparece en dos contextos geográficos distintos. En Judá, Holón era una ciudad de la serranía asignada a los levitas como ciudad sacerdotal (Josué 15:51; 21:15), y corresponde a Hilén en el pasaje paralelo de Crónicas. En Moab, otra Holón aparece en el oráculo de Jeremías contra Moab (Jeremías 48:21). Este uso dual probablemente representa dos localidades distintas que comparten el mismo nombre, fenómeno frecuente en la geografía del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2474', 'spa', 'Ventana: una abertura en un muro o estructura para luz, aire y observación', 'Ventana: una abertura en un muro o estructura para luz, aire y observación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2477', 'spa', 'Jalaj: distrito asirio donde fueron asentados los exiliados israelitas tras la caída de Samaria', 'Ciudad o distrito bajo dominio asirio adonde fueron deportados los cautivos israelitas tras la caída de Samaria en el 722 a.C. Se menciona en los relatos históricos del exilio asirio junto al río Jabor y las ciudades de los medos. Los estudiosos la han identificado con Ḫalaḫḫu en Mesopotamia, aunque algunos sugieren Cilicia. El nombre señala uno de los trágicos destinos de la deportación del reino del norte, y representa la dispersión de Israel entre las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2479', 'spa', 'Angustia, dolor convulsivo; aflicción física o emocional severa comparada con dolores de parto que atenaza los lomos.', 'Sustantivo vívido que expresa angustia o dolor convulsivo, siempre asociado a los lomos (מָתְנַיִם), sede de la fuerza en la anatomía hebrea. Cuando חַלְחָלָה llena los lomos, señala el colapso total de la entereza física y emocional. Isaías 21:3 lo emplea para la reacción corporal del profeta ante la visión de la caída de Babilonia. Nahúm 2:10 y Ezequiel 30:4, 9 lo aplican al terror que se apoderará de las naciones bajo el juicio de Dios, transmitiendo una cualidad visceral y corporal de la aflicción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2483', 'spa', 'Enfermedad, dolencia, mal — padecimiento físico o aflicción, a veces metáfora de la angustia nacional', 'Enfermedad, dolencia, mal — padecimiento físico o aflicción, a veces metáfora de la angustia nacional');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2485', 'spa', 'Flauta o caramillo — instrumento de viento usado tanto en celebraciones como en duelos.', 'Sustantivo masculino que designa un instrumento de viento, probablemente una flauta de caña o caramillo. Aparece en contextos festivos: el pueblo tocando flautas en la coronación de Salomón con tal estruendo que la tierra tembló (1 Re 1:40), y en listas de instrumentos durante banquetes (Is 5:12). Isaías 30:29 lo asocia con procesiones nocturnas gozosas hacia el monte de Dios. Sin embargo, Jeremías 48:36 emplea su sonido como símil de duelo por Moab, revelando que la flauta servía tanto para la celebración como para el lamento en el antiguo Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2486', 'spa', '¡Lejos sea! — exclamación de enérgico repudio, que rechaza algo como profano o aborrecible', '¡Lejos sea! — exclamación de enérgico repudio, que rechaza algo como profano o aborrecible');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2487', 'spa', 'Muda de ropa (dada como regalo o premio); turno, relevo o cambio de servicio', 'Derivado de la raíz ḥālap (''cambiar, pasar, renovar''), חֲלִיפָה (ḥălīpāh) se refiere con mayor frecuencia a una ''muda de ropa'': un conjunto de vestiduras entregado como obsequio o apostado como premio. José envía a sus hermanos con mudas de ropa, dando a Benjamín cinco juegos (Gn 45:22). La apuesta del acertijo de Sansón en su boda involucra treinta mudas de vestidos (Jue 14:12-13, 19). Más allá de la indumentaria, el término también denota un turno o relevo en sentido más amplio: las cuadrillas de obreros de Salomón rotaban por turnos (1 R 5:14), Job anhela su ''relevo'' del duro servicio (Job 14:14), y los impíos son descritos como aquellos ''sin cambios'' -- sin reveses de fortuna (Sal 55:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2489', 'spa', 'desvalidos, indefensos, desdichados: personas vulnerables víctimas de la opresión', 'Término oscuro que aparece únicamente en el Salmo 10, donde describe a personas vulnerables acechadas por los malvados. Su significado exacto es incierto y plantea importantes cuestiones textuales. Las versiones antiguas lo entendieron como referencia a los pobres o desafortunados, mientras que la tradición masorética (reflejada en las lecturas qeré) intentó interpretaciones alternativas relacionadas con ejércitos o grupos abatidos. La mayoría de los intérpretes modernos lo consideran un adjetivo que significa «indefenso» o «desvalido», describiendo a quienes son presa fácil de los opresores. El contexto retrata consistentemente a víctimas de violencia y explotación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2490a', 'spa', 'traspasar, herir mortalmente; profanar, contaminar lo sagrado', 'Verbo cuyo sentido físico primario es perforar o traspasar, a menudo con consecuencias fatales. En uno de los versículos teológicamente más significativos de las Escrituras, el Siervo es ''herido por nuestras transgresiones'' (Is 53:5, Pual), mientras que la mano de Dios ''traspasó a la serpiente huidiza'' (Job 26:13). El clamor del salmista ''mi corazón está herido dentro de mí'' (Sal 109:22) interioriza la herida como angustia. Un sentido secundario entra en el ámbito sacro: en Ez 28:9, el orgulloso rey de Tiro enfrentará a ''los que te profanen'', donde la perforación se convierte en profanación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2490c', 'spa', 'Piel: profanar, contaminar, desacralizar; Hifil: comenzar; Nifal/Pual: ser profanado; también tratar el fruto como común.', 'Un notable homógrafo que reúne dos raíces distintas bajo una misma forma consonántica. La raíz II חלל en Piel significa profanar o desacralizar — violar lo sagrado, ya sea el nombre de Dios (Lv 19:12), el sábado (Éx 31:14) o un santuario (Ez 7:24). La raíz I חלל en Hifil significa comenzar, derivando del sentido árabe de ''desatar, soltar, abrir'' — iniciar algo nuevo liberándolo de su estado previo. La conexión puede radicar en la idea de remover el límite sagrado que marca algo como apartado, de modo que o bien se lo ''profana'' o se lo ''inaugura'' para el uso. El alemán ''entweihen'' (profanar) y ''anfing'' (comenzó) muestran cuán abruptamente divergen ambos sentidos, y sin embargo el español ''profanar'' y ''comenzar'' coexisten a lo largo de toda la Biblia hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2491a', 'spa', 'Alguien traspasado, muerto o herido de muerte; una baja de batalla o cadáver dejado por la violencia.', 'Alguien traspasado, muerto o herido de muerte; una baja de batalla o cadáver dejado por la violencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2491b', 'spa', 'Profanado, mancillado, deshonrado; persona contaminada ceremonial o moralmente, distinto de חָלָל I (''muerto en batalla'').', 'Adjetivo que significa profanado o mancillado, distinto del mucho más frecuente חָלָל I (''traspasado, muerto en batalla''). Mientras חָלָל I se refiere a víctimas del campo de batalla, esta palabra describe a personas que han quedado ceremonial o moralmente contaminadas. En Levítico 21:7, 14, se aplica a una mujer sexualmente deshonrada: un sacerdote no puede casarse con ella. En Ezequiel 21:25, 29, califica a un ''profano e impío'', probablemente un gobernante cuya autoridad ha sido profanada por su infidelidad. El sentido apunta siempre a la contaminación, nunca a la muerte violenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2492b', 'spa', 'Soñar; de visiones ordinarias durante el sueño y especialmente sueños proféticos o revelatorios; como participio, un soñador', 'Soñar; de visiones ordinarias durante el sueño y especialmente sueños proféticos o revelatorios; como participio, un soñador');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2493', 'spa', 'Sueño (arameo); una visión durante el dormir, especialmente una revelación divina a reyes y profetas en Daniel', 'Sueño (arameo); una visión durante el dormir, especialmente una revelación divina a reyes y profetas en Daniel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2496', 'spa', 'Pedernal; piedra extremadamente dura usada figuradamente para expresar firmeza inquebrantable', 'חַלָּמִישׁ designa el pedernal, la piedra común más dura conocida en el mundo antiguo. En Deuteronomio 8:15, Dios hace brotar agua de la ''roca de pedernal'' en el desierto, un acto magnificado por la notoria impermeabilidad de este material. Isaías 50:7 lo emplea como poderoso símil de determinación inquebrantable: ''Puse mi rostro como pedernal.'' El español ''pedernal'' y el inglés ''flint'' convergen en la misma imagen mineralógica, mientras que las traducciones alemana y francesa dejan el hebreo sin traducir, subrayando la especificidad técnica del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2497', 'spa', 'Helón; padre de Eliab, líder de la tribu de Zabulón durante el período del desierto', 'Helón (חֵלֹן) aparece exclusivamente en Números como padre de Eliab, quien sirvió como jefe tribal de Zabulón durante el censo y la marcha por el desierto. Sus cinco apariciones se concentran en los primeros capítulos de Números (1:9; 2:7; 7:24, 29; 10:16), siempre dentro de la fórmula patronímica «Eliab hijo de Helón». La Septuaginta transcribe el nombre como Χαιλών o Χελών. La uniformidad del nombre en español, francés, inglés y alemán —todos «Helon»— confirma la estabilidad de esta tradición onomástica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2498', 'spa', 'Pasar, irse; también cambiar, intercambiar, renovar, traspasar o transgredir. Raíz versátil que abarca movimiento, transformación y violación', 'Pasar, irse; también cambiar, intercambiar, renovar, traspasar o transgredir. Raíz versátil que abarca movimiento, transformación y violación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2499', 'spa', 'Pasar por encima (arameo); del tiempo que transcurre sobre una persona, usado exclusivamente de los ''siete tiempos'' decretados sobre Nabucodonosor.', 'Verbo arameo que significa ''pasar por encima'', empleado en Daniel 4 exclusivamente para describir el tiempo que transcurre sobre Nabucodonosor durante su período de locura. Siete ''tiempos'' (estaciones o años) deben pasar sobre el rey antes de que recupere la razón y reconozca la soberanía del Altísimo. El verbo aparece cuatro veces —en el decreto, su interpretación, su reiteración y su cumplimiento— creando un poderoso eco narrativo que subraya la inexorabilidad del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2502a', 'spa', 'Sacar, librar, rescatar; Piel: rescatar del peligro; Nifal: ser librado; Qal: quitar, despojar; también arrancar, saquear o retirarse', 'Sacar, librar, rescatar; Piel: rescatar del peligro; Nifal: ser librado; Qal: quitar, despojar; también arrancar, saquear o retirarse');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2502b', 'spa', 'Equipar o armar para la guerra (participio pasivo Qal: hombres armados); armarse (Nifal reflexivo); fortalecer o fortificar (Hifil)', 'Equipar o armar para la guerra (participio pasivo Qal: hombres armados); armarse (Nifal reflexivo); fortalecer o fortificar (Hifil)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2503', 'spa', 'Heles; nombre de dos hombres: un valiente de David y un judahíta del linaje de Jerameel', 'Heles (חֶלֶץ) designa a dos individuos distintos en la Biblia hebrea. El primero es uno de los treinta guerreros de élite de David, llamado «el paltita» en 2 Samuel 23:26 y «el pelonita» en 1 Crónicas 11:27, quien además comandaba la séptima división mensual del ejército (1 Cr 27:10). El segundo Heles figura en la genealogía de Judá en 1 Crónicas 2:39. El BDB conecta el nombre con la raíz que significa «vigor». Las variantes en español y francés («Heles», «Hélets», «Jelets») reflejan leves diferencias de transliteración entre tradiciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2504', 'spa', 'Lomos, la parte media del cuerpo vista como sede de la fuerza, el poder generativo y el lugar donde se ciñe el cinturón', 'Apareciendo siempre en forma dual (חֲלָצַיִם, chalatsayim), este sustantivo designa los lomos o la cintura -- el centro del cuerpo humano entendido como fuente tanto de fuerza física como de poder generativo. La promesa de Dios a Jacob en Betel -- ''reyes saldrán de tus lomos'' (Gn 35:11) -- establece el sentido reproductivo, retomado en la dedicación del Templo de Salomón (1 R 8:19; 2 Cr 6:9). El desafío a Job de ''ceñir tus lomos como un hombre'' (Job 38:3; 40:7) evoca la imagen de sujetar la parte media del cuerpo para la acción vigorosa. Isaías 11:5 corona el retrato mesiánico: ''la fidelidad será el cinturón de sus lomos'' -- la justicia no meramente vestida, sino encarnada. El caritativo Job es bendecido porque los lomos del pobre, ''calentados'' por sus vestiduras, lo alaban (Job 31:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2505a', 'spa', 'dividir, repartir, distribuir; repartir tierra, botín o herencia entre los destinatarios', 'dividir, repartir, distribuir; repartir tierra, botín o herencia entre los destinatarios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2505b', 'spa', 'Ser liso o resbaladizo; Hifil: alisar, adular con palabras engañosas; también dividirse (del corazón).', 'Una raíz cuyo sentido físico —liso, resbaladizo— genera un rico campo metafórico. El Hifil «alisar» se aplica literalmente al artesano que pule con el martillo (Is 41:7), pero con mayor frecuencia describe el habla peligrosamente pulida: la mujer extraña que «alisa sus palabras» (Pr 2:16; 7:5), el que se adula en el Salmo 36:2, y el malvado cuyas palabras «son más suaves que la mantequilla» (Sal 55:21). Proverbios 28:23 observa que la reprensión honesta gana más favor que la lengua aduladora. Oseas 10:2 puede conservar un juego de palabras con la raíz homónima חלק I (''dividir''): «su corazón es liso/dividido», doble sentido que el profeta pudo buscar intencionalmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2506a', 'spa', 'Porción, parte o parcela asignada; la parte que le corresponde a alguien de bienes, tierra o herencia pactual.', 'Porción, parte o parcela asignada; la parte que le corresponde a alguien de bienes, tierra o herencia pactual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2508', 'spa', 'porción, parte asignada, posesión: sustantivo arameo que designa lo que se otorga o corresponde por derecho', 'Sustantivo arameo que significa porción, parte o lote asignado. En Esdras se refiere a posesión territorial o derecho legal, mientras que en Daniel describe la porción designada por decreto divino. La palabra conlleva matices de lo que se asigna legítima u oficialmente a alguien. En las visiones apocalípticas de Daniel, describe la porción asignada a las bestias por soberanía divina. El término enfatiza el concepto de partes medidas y distribuidas, no una posesión irrestricta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2509', 'spa', 'Liso, suave; literalmente de la piel o el terreno, figuradamente del habla aduladora o engañosa.', 'Adjetivo que significa liso o suave, abarcando un vívido espectro desde la textura física hasta el discurso engañoso. Jacob es llamado אִישׁ חָלָק (''hombre de piel lisa'') en contraste con la vellosidad de Esaú (Gn 27:11), anclando la palabra en la experiencia táctil. Josué menciona un ''monte liso'' (Jos 11:17; 12:7), aplicándola a un terreno pelado y sin árboles. Pero los usos más cargados teológicamente son figurados: Proverbios 5:3 advierte que la boca de la mujer ajena es ''más suave que el aceite'', y Ezequiel 12:24 condena la ''adivinación lisonjera'' —adulación disfrazada de profecía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2513a', 'spa', 'Porción o parcela de terreno; un campo concreto de tierra, o una parte asignada o porción de herencia.', 'Porción o parcela de terreno; un campo concreto de tierra, o una parte asignada o porción de herencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2513b', 'spa', 'Suavidad, lisonja; piel lisa o terreno resbaladizo, siempre con matices de engaño o peligro.', 'Chelqah (II) toma la cualidad física de la suavidad y la extiende al terreno moral y existencial. Los labios lisonjeros hablan chelaqot, palabras suaves que ocultan un corazón doble (Sal 12:2-3), y la adúltera seduce con «la suavidad de su lengua» (Pr 6:24). Isaías 30:10 registra a Israel exigiendo que los profetas hablen «cosas agradables» en lugar de la verdad. Sin embargo, la palabra también conserva sentidos físicos: la piel lisa del cuello de Jacob que posibilitó su engaño a Isaac (Gn 27:16), y el terreno resbaladizo donde Dios coloca a los malvados antes de su ruina (Sal 73:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2518', 'spa', 'Hilcías: nombre propio teofórico masculino que significa ''mi porción es YHWH'', llevado por varios sacerdotes y levitas', 'Hilcías: nombre propio teofórico masculino que significa ''mi porción es YHWH'', llevado por varios sacerdotes y levitas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2519', 'spa', 'Suavidad, resbaladero; en sentido figurado, adulación o intrigas engañosas.', 'Derivado de una raíz que transmite lisura o lo resbaladizo, este sustantivo pinta un cuadro vívido de terreno traicionero y discurso engañoso. En el Salmo 35:6 y Jeremías 23:12 describe un camino de tinieblas y suelo resbaladizo que los impíos deben transitar. En Daniel 11:21 y 11:34, la misma palabra se traslada al ámbito político, denotando intrigas astutas o adulación mediante las cuales un gobernante usurpa el poder. ''Resbaladeros'' capta el sentido físico, mientras que ''intrigas'' refleja la extensión figurada hacia el engaño calculado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2522', 'spa', 'debilitar, postrar, incapacitar: verbo que describe el paso de la fuerza a la debilidad', 'Verbo que describe el debilitamiento físico o la postración. Aparece tanto en sentido activo (debilitar o incapacitar a un adversario) como en sentido estativo (quedar debilitado o postrado). Éxodo lo emplea para la derrota de Amalec por Josué, Job lo aplica a la mortalidad y fragilidad humana, e Isaías lo usa para la caída de orgullosos opresores. La raíz transmite la transición de la fortaleza a la debilidad, de estar en pie a caer, del poder a la indefensión. Ya sea describiendo derrota militar, decadencia mortal o derrocamiento de tiranos, el verbo enfatiza la debilitación y el colapso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2524', 'spa', 'Suegro (padre del esposo de una mujer).', 'Término de parentesco que designa específicamente al padre del esposo de una mujer. Las cuatro ocurrencias bíblicas aparecen en narrativas de crisis familiar: Judá es llamado suegro de Tamar en Génesis 38:13 y 38:25, mientras que Elí es identificado como suegro de la esposa de Finees en 1 Samuel 4:19 y 4:21. La palabra es cognada con términos del árabe, arameo, etiópico y acadio para el pariente varón del esposo, lo que evidencia un vocabulario compartido de parentesco semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2526', 'spa', 'Cam — segundo hijo de Noé y antepasado de los pueblos africanos y cananeos; también nombre poético para Egipto. El nombre propio Cam (חָם), uno de los', 'Cam — segundo hijo de Noé y antepasado de los pueblos africanos y cananeos; también nombre poético para Egipto. El nombre propio Cam (חָם), uno de los tres hijos de Noé que sobrevivieron al diluvio (Gn 5:32; 6:10; 7:13; 9:18). Es identificado como padre de Canaán (Gn 9:22) y antepasado de cuatro grandes grupos de pueblos: Cus (Etiopía), Mizraim (Egipto), Fut (Libia) y Canaán (Gn 10:6, 20; 1 Cr 1:8). El relato de la indiscreción de Cam hacia su padre (Gn 9:22) conduce al oráculo contra Canaán. En los Salmos tardíos, ''tierra de Cam'' se convierte en sinónimo poético de Egipto (Sal 78:51; 105:23, 27; 106:22), siempre en paralelo con Mizraim. Primera Crónicas 4:40 también ubica habitantes camitas anteriores en el Neguev.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2527', 'spa', 'Calor o calidez; la intensidad abrasadora del sol del mediodía, el arrebato de la pasión, la temperatura del pan caliente y el confort del calor corporal.', 'Un sustantivo compacto que abarca todo tipo de calor que una persona experimenta en el antiguo Cercano Oriente. Su uso más frecuente es el sofocante ''calor del día'' bajo el cual Abraham estaba sentado a la puerta de su tienda (Gn 18:1) y el ejército de Saúl marchó a la batalla (1 S 11:11). Dios promete que el ritmo de las estaciones nunca cesará: ''siembra y siega, frío y calor'' (Gn 8:22). Jeremías advierte que el árbol plantado junto al agua ''no teme cuando viene el calor'' (Jer 17:8), mientras Isaías habla del calor de la cosecha que relumbra antes de la vendimia (Is 18:4). El uso figurado del ''calor de la pasión'' en Jeremías 51:39 y el sencillo ''pan caliente'' de 1 Samuel 21:7 muestran que la palabra trasciende el clima para alcanzar la emoción y la vida cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2529a', 'spa', 'Cuajada, leche cuajada -- producto lácteo espeso de vacas, ovejas o cabras, que denota abundancia pastoral', 'El sustantivo חֶמְאָה (chem''ah) designa la cuajada o leche cuajada, un alimento básico de la vida pastoral en el antiguo Cercano Oriente. Abraham puso cuajada y leche ante sus tres visitantes en Mamre (Gn 18:8), y Jael ofreció a Sísara cuajada en un tazón señorial (Jue 5:25). El cántico de Moisés celebra la abundancia de la tierra con ''cuajada del ganado y leche del rebaño'' (Dt 32:14). El término también aparece en contextos sapienciales y poéticos: Job 20:17 imagina ríos de cuajada y miel, mientras que Proverbios 30:33 observa que batir la leche produce mantequilla. La imagen evoca consistentemente riqueza, hospitalidad y la buena vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2529b', 'spa', 'calor, furor, ira; también veneno, ponzoña (de la raíz que significa «estar caliente»)', 'Este poderoso término capta la sensación física de calor ardiente y su paralelo psicológico en la ira humana. Su campo semántico se extiende desde la fiebre literal, como en Oseas 7:5 («fiebre del vino»), hasta el calor metafórico de la ira divina que aparece repetidamente en los oráculos proféticos de juicio. Resulta interesante que las lenguas cognadas conservan tanto el sentido de «calor» como el de «veneno»: el árabe y el siríaco pueden significar ponzoña, mientras que el acadio imtu designa aliento o veneno. El término aparece frecuentemente con sufijos posesivos en contextos donde la ira de Dios es derramada, creando vívidas imágenes de la ira como algo ardiente, consumidor y mortal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2530a', 'spa', 'Desear o codiciar; como participio, deseable o precioso; en Piel, deleitarse intensamente.', 'Desear o codiciar; como participio, deseable o precioso; en Piel, deleitarse intensamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2530b', 'spa', 'Sustantivo femenino que significa ''preciosidad, cosas deseables, tesoros''; también ''manjares, alimento selecto''', 'Derivado de la raíz חמד (''desear''), este sustantivo expresa la cualidad de ser profundamente deseable o precioso. Su uso más notable aparece en el epíteto de Daniel, אִישׁ חֲמֻדוֹת (''varón de tesoros''), que significa alguien grandemente amado por Dios (Daniel 9:23; 10:11, 19). También describe bienes materiales valiosos: el botín precioso de 2 Crónicas 20:25, los tesoros de Egipto en Daniel 11:43 y las piedras costosas de Daniel 11:38. En un uso especializado denota manjares o alimentos selectos, cuando Daniel se abstiene de לֶחֶם חֲמֻדוֹת (''pan de cosas deseables'') durante su ayuno (Daniel 10:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2531', 'spa', 'Deseo, deleite, preciosidad — aquello que es atractivo, agradable o codiciado.', 'Sustantivo masculino que expresa lo deseable o deleitoso. Aparece siempre tras un sustantivo en estado constructo y funciona como atributo intensificador: «viñas de deleite» (Am 5:11), «campos de deleite» (Is 32:12) y «jóvenes deseables», es decir, hombres atractivos y codiciados (Ez 23:6, 12, 23). «Deleite» y «delicia» captan el placer estético, mientras que «deseo» enfatiza el anhelo. La palabra eleva lo ordinario a la categoría de lo codiciado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2532a', 'spa', 'Deseo, deleite o preciosidad; algo anhelado, deleitoso o atesorado como valioso. Chemdah captura la atracción magnética de algo que cautiva el corazón', 'Deseo, deleite o preciosidad; algo anhelado, deleitoso o atesorado como valioso. Chemdah captura la atracción magnética de algo que cautiva el corazón — ya sea el sentimiento de deseo en sí o la cualidad que hace deseable a un objeto. Cuando Samuel dice a Saúl que ''todo el deseo de Israel'' reposa en él (1 Sam 9:20), la palabra oscila entre el anhelo del pueblo y la deseabilidad de Saúl como rey. La famosa profecía de Hageo de que ''el chemdah de todas las naciones vendrá'' (Hag 2:7) se ha leído como tesoro, deseo, o mesiánicamente. Jeremías lamenta su ''porción deleitosa'' pisoteada (Jer 12:10), y Oseas advierte que los ''objetos preciosos'' de Efraín serán saqueados (Os 13:15). A lo largo de su rango, la palabra insiste en que el verdadero valor y el verdadero anhelo son dos caras de la misma moneda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2534', 'spa', 'Calor, ira, furor, furia; cólera intensa especialmente de Dios; también veneno o ponzoña de serpientes.', 'חֵמָה es una de las palabras más viscerales del hebreo bíblico para la ira — etimológicamente enraizada en el calor (de יָחַם, ''estar caliente''), denota la furia ardiente que se levanta en Dios o en los seres humanos cuando se los provoca más allá de toda tolerancia. De sus 124 ocurrencias, la inmensa mayoría describen la ira divina: la חֵמָה de Dios ''se derrama'' como fuego (Nah 1:6), ''arde'' contra Israel (2 R 22:17) y debe ser ''apartada'' mediante arrepentimiento o intercesión. Pero חֵמָה posee un segundo significado enteramente distinto — ''veneno, ponzoña'' — que aparece seis veces en relación con serpientes (Dt 32:24, 33; Sal 58:5). Este sentido homónimo preserva una antigua conexión semítica entre calor y veneno, hallada también en el árabe حُمَّى (''fiebre/ponzoña'') y el arameo יַחְמָא, sugiriendo que la sensación ardiente de la mordedura de serpiente dio a ambos significados su raíz común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2535', 'spa', 'Sol (sinónimo poético de shemesh); calor del sol.', 'Sustantivo poético para designar el sol, de tono elevado y literario, que aparece únicamente en poesía y profecía como alternativa solemne al cotidiano shemesh. Isaías lo empareja con levanah («luna») en visiones escatológicas donde el sol se «avergüenza» ante la gloria de Dios (Is 24:23; 30:26). Cantares 6:10 lo emplea en el impresionante retrato de la amada: «resplandeciente como el sol». En Salmo 19:6, el enfoque pasa del cuerpo celeste a su calor penetrante, del cual nada puede esconderse. Los testimonios multilingües confirman esta distinción: «sol» para el astro y «calor» para su radiación térmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2537', 'spa', 'Hamutal; madre de los reyes Joacaz y Sedequías, hija de Jeremías de Libna', 'Hamutal (חֲמוּטַל) fue esposa del rey Josías y madre de dos de los últimos reyes de Judá: Joacaz y Sedequías. Su nombre posiblemente significa «mi suegro es el rocío», conectándose con el nombre Abital por construcción paralela. Aparece en momentos decisivos del declive de Judá, mencionada en las fórmulas de acceso al trono de ambos hijos (2 R 23:31; 24:18; Jer 52:1). La variación entre la escritura ketiv (חֲמִיטַל) y la lectura qere (חֲמוּטַל) revela una divergencia textual temprana preservada a lo largo de las tradiciones manuscritas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2538', 'spa', 'Hamul: nieto de Judá por línea de Fares, nombre que significa ''perdonado'' o ''compadecido''', 'Nombre propio que significa ''perdonado'' o ''compadecido'', perteneciente a un nieto de Judá. Hamul fue hijo de Fares y formó parte del linaje de Judá que eventualmente conduciría a David y a la línea mesiánica. Su nombre aparece en las listas genealógicas que trazan la estructura familiar de la tribu de Judá. Como ancestro del clan de los hamulitas, su nombre identificó una de las subdivisiones de la tribu durante el período del desierto y el asentamiento en Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2543', 'spa', 'Hamor es la palabra hebrea estándar para el asno macho, uno de los animales de mayor importancia económica en el mundo bíblico. Los burros aparecen en', 'Hamor es la palabra hebrea estándar para el asno macho, uno de los animales de mayor importancia económica en el mundo bíblico. Los burros aparecen en los inventarios de riqueza patriarcal junto con ovejas, ganado y camellos (Gn 12:16; 24:35), sirvieron como monturas cotidianas mucho antes de que los caballos se popularizaran en Israel (Nm 22:21; Jue 10:4), y transportaban cargas en viajes largos (Gn 42:26; 1 S 25:18). La palabra también aparece en contextos legales: el primogénito del asno debe ser redimido con un cordero (Éx 13:13; 34:20), y el descanso sabático se extiende al asno (Éx 23:12; Dt 5:14). Isacar es comparado memorablemente con un ''asno fuerte'' que se recuesta entre las alforjas (Gn 49:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2544', 'spa', 'Hamor — jefe heveo, padre de Siquem, cuyo clan interactuó con la familia de Jacob en Siquem.', 'El nombre propio del gobernante heveo de la ciudad de Siquem y padre del príncipe Siquem, quien agredió a Dina. Sus 13 ocurrencias se concentran en Génesis 33-34 y se extienden hasta Josué 24:32 (la parcela que Jacob le compró) y Jueces 9:28 (una memoria política posterior). El nombre mismo significa ''asno'', posiblemente reflejando un simbolismo de animal de pacto atestiguado en otras culturas semíticas. Las traducciones lo transliteran uniformemente: en español ''Hamor'' o ''Jamor''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2545', 'spa', 'Suegra — la madre del esposo o de la esposa, figura central en la narrativa de Rut', 'El sustantivo חָמוֹת (chamot) designa específicamente a la suegra, y sus apariciones se concentran casi por completo en el libro de Rut, donde la relación entre Noemí y Rut constituye el corazón emocional y teológico del relato. La lealtad de Rut hacia su suegra —«tu pueblo será mi pueblo, y tu Dios mi Dios» (Rut 1:16)— redefine la familia más allá de los lazos de sangre. El término aparece en cada momento decisivo de la narrativa: la partida (Rut 1:14), la espiga (2:11, 18-19, 23) y el plan en la era (3:1, 6, 16-17). Miqueas 7:6 emplea la misma palabra en su retrato de desintegración social, donde la nuera se levanta contra su suegra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2549', 'spa', 'Quinto (número ordinal) o una quinta parte (fracción); usado en enumeraciones y en contextos legales de restitución', 'Quinto (número ordinal) o una quinta parte (fracción); usado en enumeraciones y en contextos legales de restitución');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2550', 'spa', 'Perdonar, tener compasión o mostrar piedad absteniéndose de la destrucción o el trato severo', 'Perdonar, tener compasión o mostrar piedad absteniéndose de la destrucción o el trato severo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2552', 'spa', 'Estar o volverse caliente; causativamente, calentar; reflexivamente, calentarse; figuradamente, inflamarse de pasión.', 'Un verbo enraizado en la simple sensación física de calidez, que abarca desde el derretimiento del maná bajo el sol matutino (Éx 16:21) hasta la íntima escena donde el cuerpo de Eliseo devuelve el calor al niño muerto (2 R 4:34). Sus variaciones de tema trazan un arco natural: Qal para volverse caliente, Piel para calentar algo, Hitpael para calentarse uno mismo y Nifal para inflamarse de deseo. El Nifal figurado de Isaías 57:5 — ''los que se encienden'' — revela cómo la misma raíz pasa del confort al exceso cultual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2553', 'spa', 'Pilares solares o altares de incienso; objetos cultuales asociados al culto solar cananeo, siempre condenados en la Escritura.', 'Los חַמָּנִים son instalaciones cultuales vinculadas al culto pagano, probablemente estelas dedicadas a una deidad solar o altares especializados de incienso usados en el culto a Baal. Cada aparición lleva un tono de condena. Levítico 26:30 amenaza con su destrucción junto a los lugares altos. El Cronista registra su eliminación durante las reformas de Asá (2 Cr 14:5) y Josías (2 Cr 34:4, 7). Isaías contempla su demolición como parte de la futura purificación de Israel (Is 17:8; 27:9). El cognado palmireno חַמָּנָא confirma la asociación solar, y aparecen consistentemente junto a otros símbolos de idolatría: las aseras, los altares de Baal y las imágenes talladas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2554', 'spa', 'Tratar con violencia, hacer mal; arrancar o derribar; sacudir (de una vid); pasivo: ser violentado.', 'La raíz hebrea חמס lleva la energía cruda de la fuerza injusta: violencia que transgrede los límites morales. Su uso más frecuente es la agresión activa contra los vulnerables: viudas y huérfanos (Jer 22:3), o sacerdotes que profanan la ley de Dios (Ez 22:26; Sof 3:4). Pero la raíz se extiende a territorio sorprendente: una vid que «sacude» sus uvas verdes (Job 15:33) y Dios mismo arrancando violentamente su propio tabernáculo (Lm 2:6). El Nifal pasivo completa el cuadro: quienes sufren violencia la reciben como víctimas (Jer 13:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2555', 'spa', 'El hebreo חָמָס abarca un espectro que va desde la brutalidad física hasta formas más sutiles de injusticia y agravio moral. Cuando Dios ve la tierra ', 'El hebreo חָמָס abarca un espectro que va desde la brutalidad física hasta formas más sutiles de injusticia y agravio moral. Cuando Dios ve la tierra llena de חָמָס antes del Diluvio (Gn 6:11), la palabra engloba la corrupción total de la conducta humana. Sin embargo, cuando Agar agravia a Sara (Gn 16:5), o cuando un testigo malicioso se levanta contra alguien (Dt 19:16), la dimensión física se desvanece y la violación ética ocupa el primer plano. El español ''violencia'' se ajusta bien al sentido físico, mientras que la dimensión moral a veces requiere otro vocabulario, una amplitud que el hebreo contiene en un solo término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2556a', 'spa', 'Leudarse, fermentar; en sentido figurado, amargarse o agriarse de corazón.', 'En su raíz, este verbo describe el proceso químico de la fermentación: la masa que sube por la acción de la levadura. En Éxodo 12:34 y 12:39 aparece en la urgencia narrativa del Éxodo: los israelitas salieron de Egipto antes de que su masa pudiera leudarse. Oseas 7:4 emplea la imagen de la masa dejada fermentar como metáfora de la corrupción moral. El Hitpael en el Salmo 73:21 gira el sentido hacia lo interior: el corazón del salmista ''se amargaba'', agriado por la envidia y el resentimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2557a', 'spa', 'Pan con levadura — pan o alimento elaborado con levadura, prohibido durante la Fiesta de los Panes sin Levadura', 'El adjetivo sustantivado חָמֵץ (chamets) designa el pan con levadura o cualquier alimento que contenga fermento. Su importancia es principalmente ritual: durante la Pascua y los siete días de la Fiesta de los Panes sin Levadura, todo chamets debía ser eliminado de los hogares israelitas (Éx 12:15; 13:3, 7). La prohibición se extiende a las ofrendas del altar: ninguna ofrenda de cereal podía prepararse con levadura (Lv 2:11), aunque los panes leudados acompañaban la ofrenda de paz por acción de gracias (Lv 7:13). La sangre del sacrificio no debía ofrecerse «con pan con levadura» (Éx 23:18; 34:25). En español, «pan con levadura» o «pan leudado» expresan la distinción ritual que otorga fuerza a este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2558', 'spa', 'Vinagre o vino agrio — líquido ácido usado como condimento, bebida y en símiles proverbiales.', 'Sustantivo masculino para vinagre o vino agrio, un condimento común en el antiguo Cercano Oriente. Rut mojó su pan en vinagre en la mesa de Booz (Rt 2:14), mientras que el voto nazareo prohibía expresamente tanto el vinagre de vino como el vinagre de cerveza (Nm 6:3). Proverbios lo emplea memorablemente en símiles: vinagre en los dientes para el efecto irritante del perezoso (Pr 10:26), y vinagre sobre soda para la futilidad de cantar canciones a un corazón afligido (Pr 25:20). El salmista lo recibió en lugar de agua como acto de crueldad (Sal 69:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2560a', 'spa', 'Fermentar, espumear o agitarse; de aguas turbulentas o entrañas revueltas por la angustia', 'Este verbo evoca el burbujeo turbulento de la fermentación o el oleaje violento del agua. En el Salmo 75:8, el vino espumea en la copa de Dios como señal de juicio divino. El Salmo 46:3 describe aguas que rugen y se agitan, imagen teofánica de conmoción cósmica. Lamentaciones 1:20 y 2:11 trasladan la imagen al plano visceral: las entrañas del poeta se revuelven de angustia por la destrucción de Jerusalén. El término abarca tanto la agitación física de los líquidos como el tormento interior del ser humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2562', 'spa', 'Vino; término arameo para la bebida fermentada de uva, usado en decretos oficiales y contextos de banquetes reales.', 'Sustantivo arameo para vino, cognado del término poético hebreo chemer. Aparece en dos contextos distintos: decretos imperiales persas que autorizan provisiones para el templo (Esd 6:9; 7:22) y el célebre banquete de Belsasar donde se profanaron los vasos sagrados (Dn 5:1, 2, 4, 23). El cognado siríaco confirma el significado básico. Que esta única palabra conecte solemnes concesiones administrativas con festines reales desenfrenados refleja el doble papel del vino en el antiguo Cercano Oriente: sustento esencial y catalizador de la soberbia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2563a', 'spa', 'Arcilla, mortero o lodo; material terroso moldeado por alfareros, usado en construcción o hallado como barro en las calles. חֹמֶר es una de las palabr', 'Arcilla, mortero o lodo; material terroso moldeado por alfareros, usado en construcción o hallado como barro en las calles. חֹמֶר es una de las palabras más táctiles de la Biblia hebrea: casi se puede sentir la tierra húmeda entre los dedos. En su uso teológico más resonante, es la arcilla del alfarero con la que Dios forma a la humanidad: ''nosotros somos el barro, tú el alfarero'' (Is 64:8; cf. Is 29:16; 45:9; Job 10:9). Job lamenta que los cuerpos humanos son meras ''casas de barro'' (Job 4:19), frágiles y fácilmente aplastados. La palabra también tiene un lado práctico: los constructores de Babel usaron חֹמֶר como mortero con sus ladrillos (Gn 11:3), y los capataces egipcios forzaron a Israel a trabajar ''con mortero y ladrillo'' (Éx 1:14). En su sentido más humilde, חֹמֶר es el lodo de las calles, el fango que Isaías invoca para las naciones pisoteadas (Is 10:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2563b', 'spa', 'montón, pila (especialmente de agua o de cosas muertas)', 'Sustantivo que designa un montón o pila, empleado en dos contextos distintos. En Éxodo describe los montones de ranas muertas acumuladas durante la plaga sobre Egipto. En la poesía teofánica de Habacuc aparece en una frase difícil sobre ''el montón de grandes aguas'', describiendo posiblemente mares agitados u olas espumosas. El término enfatiza la acumulación y el amontonamiento, ya sea de cadáveres o de aguas turbulentas. La conexión entre ambos usos radica en la imagen visual de cosas amasadas en confusión o abundancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2563c', 'spa', 'Homer, medida de áridos de unos 220 litros (10 efas); también barro o argamasa', 'El homer como unidad de medida de áridos era el mayor volumen estándar en el antiguo Israel, equivalente a diez efas o aproximadamente 220 litros (6,25 bushels). Ezequiel 45:11 define explícitamente la relación: «el efa y el bato serán de una misma medida, la décima parte de un homer». Se empleaba para medir cebada (Os 3:2; Ez 45:13), trigo (Ez 45:13) y grano de siembra para la tasación de tierras (Lv 27:16). Isaías 5:10 lo usa en un oráculo de juicio: diez yugadas de viña producirán solo un bato, y un homer de semilla rendirá apenas un efa. En Isaías 41:25, la misma forma parece significar barro o argamasa — un conquistador que pisotea gobernantes «como el alfarero pisa la arcilla» — aunque este uso podría derivar de una raíz homónima distinta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2564', 'spa', 'betún, asfalto, brea (producto natural del petróleo usado para impermeabilizar)', 'Asfalto o betún natural utilizado para impermeabilización y construcción. Esta sustancia era particularmente abundante en Mesopotamia y la región del mar Muerto. Génesis describe su uso como argamasa en la construcción de la torre de Babel y su disponibilidad en el valle de Sidim. Éxodo lo menciona como material de revestimiento (junto con la brea) para la canasta que protegió al bebé Moisés del agua. El término se refiere a un producto petrolero natural que se endurece y proporciona excelentes propiedades de sellado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2568', 'spa', 'Cinco; numeral cardinal, también en compuestos quince y decimoquinto, y con valor ordinal para ''quinto''.', 'El numeral hebreo חָמֵשׁ aparece 345 veces a lo largo del Antiguo Testamento, cumpliendo una función que va mucho más allá de un simple número. Forma el compuesto ''quince'' (חֲמֵשׁ עֶשְׂרֵה) y participa en expresiones ordinales para ''quinto'' y ''decimoquinto'' — sobre todo en fórmulas de datación para festividades y visiones proféticas. La visión inaugural de Ezequiel se fecha ''en el quinto día del mes'' (Ez 1:1-2), mientras que Levítico 23:6 sitúa la Fiesta de los Panes sin Levadura ''el día quince''. Los cognados recorren toda la familia semítica — arameo חֲמֵשׁ, árabe خَمْسٌ, etiópico ኀምስ — dando testimonio de su profunda antigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2570', 'spa', 'Vientre, abdomen; zona vulnerable del torso donde se asesta una puñalada mortal', 'Este sustantivo designa el vientre o abdomen, la parte baja del torso que algunas versiones antiguas llaman «la quinta costilla». Las cuatro apariciones se encuentran en relatos violentos de 2 Samuel, cada uno describiendo una puñalada letal en el vientre. Abner hiere a Asael en el abdomen (2 Sam 2:23), Joab venga la afrenta apuñalando a Abner en el mismo lugar (3:27), Recab y Baaná golpean a Is-boset allí (4:6), y Joab mata a Amasa de igual manera (20:10). Los idiomas lo traducen uniformemente como «vientre» o «abdomen».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2571', 'spa', 'Armado, en formación de batalla; equipado y organizado para la marcha militar', 'Este adjetivo describe a guerreros dispuestos en formación ordenada de combate, armados y listos para la acción. Aparece exclusivamente en el contexto de movimientos militares organizados de Israel: la salida de Egipto (Éx 13:18), el cruce del Jordán (Jos 1:14; 4:12) y la incursión nocturna de Gedeón (Jue 7:11). La traducción consistente en diversas lenguas —«armados» en español, «armé» en francés— refleja la disposición marcial que el término transmite, aunque su etimología exacta (posiblemente derivada de «cinco», sugiriendo filas o divisiones organizadas) sigue siendo debatida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2572', 'spa', 'Cincuenta; el número cardinal, o una unidad militar/organizativa de cincuenta hombres bajo un comandante.', 'El número cardinal hebreo «cincuenta», que aparece en medidas (el arca tiene cincuenta codos de ancho, Gn 6:15), cifras de censos, precios y edades. Las traducciones lo vierten uniformemente: spa cincuenta, fra cinquante, deu fünfzig. Sin embargo, un sentido organizativo distinto emerge en contextos militares y administrativos: «jefes de cincuenta» (Éx 18:21, 25) y los dramáticos enfrentamientos con Elías en los que se envía repetidamente «un capitán de cincuenta con sus cincuenta» (2 Re 1:9-14). Aquí el número se convierte en designación de unidad —un pelotón— y las formas sufijadas («sus cincuenta», «tus cincuenta») se refieren a los hombres bajo su mando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2573', 'spa', 'Odre, recipiente de cuero para transportar agua', 'Un sencillo recipiente de cuero para transportar agua, esta palabra aparece tres veces en la narración de Agar en Génesis 21 y es debatida en Habacuc 2:15. Cuando Abraham despide a Agar e Ismael, le entrega pan y un odre de agua (Gn 21:14). Al agotarse el agua, ella deja al niño bajo un arbusto (21:15), y Dios le abre los ojos para ver un pozo donde llena de nuevo el odre (21:19). La referencia en Habacuc 2:15 probablemente involucra otra palabra (ira), aunque el texto consonántico es idéntico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2574', 'spa', 'Hamat: una importante ciudad-estado siria sobre el Orontes, que marca el límite norte ideal de la tierra de Israel', 'Hamat: una importante ciudad-estado siria sobre el Orontes, que marca el límite norte ideal de la tierra de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2580', 'spa', 'Un sustantivo hebreo que se encuentra en el corazón de una de las frases más recurrentes de la Escritura: ''hallar חֵן a los ojos de alguien.'' En su us', 'Un sustantivo hebreo que se encuentra en el corazón de una de las frases más recurrentes de la Escritura: ''hallar חֵן a los ojos de alguien.'' En su uso dominante, חֵן designa la disposición favorable que un superior extiende a un subordinado — la buena voluntad inmerecida que Noé halló ante Dios (Gn 6:8), o que José recibió de Potifar (Gn 39:4). En la literatura sapiencial, sin embargo, חֵן se desplaza hacia una cualidad estética y personal: el encanto de la mujer virtuosa (Pr 11:16), la elegancia de una guirnalda alrededor del cuello (Pr 1:9) o la gracia derramada sobre los labios (Sal 45:3). El español ''gracia'' capta ambas dimensiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2582', 'spa', 'Henadad, jefe levita cuyos descendientes ayudaron a reconstruir los muros de Jerusalén', 'Nombre propio que significa «favor de Hadad», perteneciente a un cabeza de familia levita cuyos hijos desempeñaron un papel destacado en la restauración postexílica de Israel. En Esdras 3:9 los hijos de Henadad ayudan a supervisar la reconstrucción de los cimientos del templo. En Nehemías 3:18 y 3:24, miembros de su casa reparan secciones de la muralla de Jerusalén, y en Nehemías 10:9 un descendiente se une a los firmantes del pacto. El nombre mismo atestigua una época en que los nombres teofóricos semíticos que incorporaban al dios de la tormenta Hadad aún circulaban entre los israelitas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2583', 'spa', 'Acampar, plantar el campamento; en contextos militares, acampar contra una ciudad o enemigo, implicando asedio.', 'Derivado de una raíz que significa «inclinarse» o «declinar», este verbo describe el acto de asentarse en un lugar de descanso temporal. En su uso predominante a lo largo de las narraciones del desierto, designa a Israel plantando campamento durante su travesía: más de 40 apariciones solo en Números 33 trazan la ruta estación por estación («y acamparon en...»). Un matiz más agudo surge cuando el mismo verbo toma un objeto hostil: acampar contra una ciudad en guerra de asedio (1 S 11:1; Is 29:3), donde el acto de «asentarse» se convierte en una postura amenazante de presión militar sostenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2584', 'spa', 'Ana — madre del profeta Samuel, cuya oración y voto en Siló se convirtieron en modelo de petición fiel.', 'El nombre propio de la amada pero estéril esposa de Elcaná, quien oró en el tabernáculo de Siló y prometió dedicar a su hijo al SEÑOR. Las 13 ocurrencias se concentran en 1 Samuel 1-2, trazando su arco desde la petición angustiada (1:9-13) hasta la respuesta divina (1:19-20) y el cántico gozoso (2:1-10). Su nombre, relacionado con la raíz que significa ''gracia'' o ''favor'', resuena con el tema de la provisión divina inmerecida. La tradición griega lo transcribe como Anna, conservado en español como ''Ana''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2585', 'spa', 'Enoc/Hanoc: nombre propio llevado por el célebre antediluviano que caminó con Dios, y por hijos de Caín, Madián y Rubén. El nombre חֲנוֹךְ, que signif', 'Enoc/Hanoc: nombre propio llevado por el célebre antediluviano que caminó con Dios, y por hijos de Caín, Madián y Rubén. El nombre חֲנוֹךְ, que significa ''dedicado'' o ''iniciado'', pertenece a cuatro figuras bíblicas distintas. El más célebre es el hijo de Jared en la línea de Set, quien ''caminó con Dios y desapareció, porque Dios se lo llevó'' (Gn 5:24), un pasaje que generó ricas tradiciones sobre su traslado celestial. La misma grafía designa a un hijo de Caín (Gn 4:17), en cuyo honor se nombró la primera ciudad. Convencionalmente se distinguen otros dos portadores como ''Hanoc'': un hijo de Madián (Gn 25:4) y un hijo de Rubén (Gn 46:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2586', 'spa', 'Hanún — nombre propio que significa ''favorecido, clemente''; un rey amonita y dos constructores postexílicos', 'El nombre חָנוּן (Janún) significa «favorecido» o «clemente», derivado de la raíz חנן. El portador más destacado es Hanún hijo de Nahas, rey de Amón, quien humilló a los embajadores de David afeitándoles media barba y cortándoles las vestiduras, lo que provocó una guerra devastadora (2 S 10:1-4; 1 Cr 19:2-6). Su error de juicio — actuar según la sospecha de sus consejeros en lugar de aceptar las genuinas condolencias de David — constituye una advertencia sobre la desconfianza política. Otros dos hombres llamados Hanún aparecen entre los constructores del muro de Nehemías: uno reparó la Puerta del Valle (Neh 3:13) y otro (posiblemente la misma persona) reparó un tramo cerca de la armería (Neh 3:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2587', 'spa', 'Clemente, compasivo — atributo divino usado exclusivamente de Dios, frecuentemente emparejado con ''misericordioso''.', 'Uno de los adjetivos fundamentales en la confesión de Israel sobre el carácter de Dios. חַנּוּן aparece únicamente como predicado del SEÑOR. Sus raíces se remontan a la fórmula del pacto de Éxodo 34:6 — ''misericordioso y clemente'' — que resuena a través de los Salmos (86:15; 103:8; 111:4; 145:8), los profetas (Jl 2:13; Jon 4:2) y la literatura postexílica (2 Cr 30:9; Neh 9:17, 31). El emparejamiento casi universal con רַחוּם (''compasivo'') lo convierte en un doblete litúrgico fijo. El término transmite la calidez de la benevolencia divina inmerecida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2590a', 'spa', 'Embalsamar (un cadáver con especias aromáticas); madurar o sazonar (dicho de frutos)', 'Este verbo conecta los ámbitos de la muerte y la cosecha. En Génesis 50:2 y 50:26 describe la práctica egipcia de embalsamar: José ordena a los médicos embalsamar a su padre Jacob, y más tarde el propio José es embalsamado. El proceso implicaba especias aromáticas, lo cual enlaza con el otro sentido del verbo: en Cantares 2:13, la higuera «sazona» o madura sus brevas, evocando la dulce fragancia de los higos que alcanzan su punto. Los cognados árabes confirman el hilo semántico compartido de condimentar y preparar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2595', 'spa', 'El sustantivo femenino חֲנִית (''lanza'') designa un arma compuesta por una punta metálica fijada a un largo mango de madera, usada tanto para acometer ', 'El sustantivo femenino חֲנִית (''lanza'') designa un arma compuesta por una punta metálica fijada a un largo mango de madera, usada tanto para acometer en combate cuerpo a cuerpo como para arrojar a distancia. Sus 48 apariciones se concentran en los libros narrativos, especialmente 1-2 Samuel y Crónicas, donde figura de forma prominente en relatos de combate y autoridad real. La lanza de Saúl casi se convierte en un personaje: la arroja contra David dos veces (1 S 18:10-11; 19:9-10) y contra Jonatán una vez (1 S 20:33), y permanece clavada en el suelo como señal de su presencia real mientras duerme (1 S 26:7). La lanza de Goliat, descrita con medidas extraordinarias (1 S 17:7), simboliza el poderío filisteo. La visión profética de convertir las lanzas en podaderas (Is 2:4; Mi 4:3) obtiene su fuerza de la familiaridad con esta arma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2596', 'spa', 'Dedicar, inaugurar; instruir o iniciar a una persona o edificio para su propósito destinado', 'El verbo חָנַךְ abarca el doble sentido de dedicar un edificio e instruir a una persona. En Deuteronomio 20:5, el hombre que ha construido una casa nueva pero aún no la ha «dedicado» queda exento de ir a la batalla, mientras que Proverbios 22:6 exhorta célebremente a «instruir al niño en su camino». El cognado árabe revela un origen vívido: frotar dátiles en el paladar de un recién nacido para iniciar la lactancia. La dedicación del templo de Salomón en 1 Reyes 8:63 y 2 Crónicas 7:5 muestra la palabra en su registro más ceremonial. El sustantivo derivado חֲנֻכָּה da nombre a la fiesta de la Dedicación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2597', 'spa', 'Dedicación, ceremonia formal de consagración de un templo o imagen', 'Derivado de la raíz que significa «dedicar» o «inaugurar», este sustantivo designa una ceremonia formal de consagración. En Esdras 6:16-17, los exiliados que han regresado celebran con gozo y sacrificios la dedicación del templo reconstruido, un momento de restauración comunitaria. En Daniel 3:2-3, Nabucodonosor convoca a sus funcionarios para la dedicación de su imagen de oro, escena de idolatría imperial. La misma palabra enmarca así tanto la adoración verdadera como su falsificación. De esta raíz proviene el nombre de la festividad posterior de Janucá, que conmemora la rededicación macabea del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2598', 'spa', 'Dedicación o consagración; ceremonia inaugural que aparta un altar, templo o muralla para uso sagrado.', 'חֲנֻכָּה designa el acto formal de dedicar una estructura sagrada a Dios mediante ceremonia, sacrificio y celebración. Números 7 la emplea cinco veces para las ofrendas de dedicación del altar del tabernáculo, cuando cada jefe tribal trajo sus dones durante doce días (Nm 7:10, 11, 84, 88). El Cronista registra la dedicación del templo de Salomón (2 Cr 7:9), y Nehemías describe la gozosa dedicación de las murallas reconstruidas de Jerusalén con procesiones y música (Neh 12:27). El encabezado del Salmo 30, «cántico para la dedicación de la casa», apunta probablemente a una rededicación posterior del templo. Esta es la misma palabra que da nombre a la festividad posbíblica de Janucá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2600', 'spa', 'De balde; sin causa, gratuitamente, en vano: adverbio derivado de la raíz de ''gracia/favor''', 'De balde; sin causa, gratuitamente, en vano: adverbio derivado de la raíz de ''gracia/favor''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2601', 'spa', 'Hanamel, primo de Jeremías que le vendió un campo en Anatot como señal de esperanza durante el sitio de Jerusalén', 'Nombre propio que significa «Dios es misericordioso» (de חָנַן + אֵל). Hanamel era primo de Jeremías, hijo de Salum, quien se acercó al profeta para venderle un campo en Anatot durante el sitio babilónico de Jerusalén (Jer 32:7-12). La compra se convirtió en una poderosa señal profética de que casas, campos y viñas volverían a comprarse en la tierra. La Septuaginta traduce el nombre como Anameel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2603a', 'spa', 'חָנַן es el corazón verbal del vocabulario hebreo de la gracia — la raíz de la que brotan חֵן (''favor, gracia''), חַנּוּן (''clemente'') y תְּחִנָּה (''sú', 'חָנַן es el corazón verbal del vocabulario hebreo de la gracia — la raíz de la que brotan חֵן (''favor, gracia''), חַנּוּן (''clemente'') y תְּחִנָּה (''súplica''). En su forma Qal describe el acto libre e inmerecido de conceder bondad, característicamente por parte de Dios: ''Tendré misericordia del que tendré misericordia'' (Éx 33:19) es la declaración definitiva de la soberanía divina en la gracia. El Hitpael reflexivo invierte completamente la perspectiva, dando voz a la petición humana desesperada por esa gracia — Moisés ''suplicó'' a Dios (Dt 3:23), Salomón oró para que Israel pudiera ''hacer súplica'' en el exilio (1 R 8:33, 47). El clamor del salmista חָנֵּנִי (''¡ten piedad de mí!'') — la palabra de oración más frecuente en los Salmos — condensa toda la teología en un solo imperativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2605', 'spa', 'Hanán — nombre propio que significa ''clemente'', portado por múltiples individuos en la Biblia hebrea', 'Hanán (de janán, que significa «clemente» o «él ha sido clemente») es un nombre propio portado por varios individuos en la Biblia hebrea: un descendiente benjaminita (1 Cr 8:23), un hijo de Azel en la genealogía saulida (1 Cr 8:38; 9:44), uno de los guerreros valientes de David (1 Cr 11:43), sirvientes del templo que regresaron del exilio (Esd 2:46; Neh 7:49), levitas que asistieron a Esdras en la lectura de la Torá (Neh 8:7; 10:10, 22, 26), y un hijo de Igdalías cuya cámara en el Templo utilizó Jeremías (Jer 35:4). A pesar de la multiplicidad de portadores, el nombre funciona como una sola entrada léxica. Todas las lenguas lo conservan por transliteración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2606', 'spa', 'Hananel, torre en la muralla norte de Jerusalén entre la Puerta de las Ovejas y la Puerta del Pescado', 'Topónimo que significa «Dios es misericordioso», referido a una torre prominente en las fortificaciones septentrionales de Jerusalén. Aparece en contextos proféticos y postexílicos: Jeremías vislumbra la ciudad reconstruida medida desde la Torre de Hananel (Jer 31:38), Zacarías describe el allanamiento escatológico del terreno de Jerusalén desde esta torre hasta los lagares del rey (Zac 14:10), y Nehemías registra su reconstrucción junto a la Puerta de las Ovejas (Neh 3:1; 12:39).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2607', 'spa', 'Hanani — nombre propio que significa ''lleno de gracia, mi gracia''; usado por varios sacerdotes, profetas y líderes', 'El nombre חֲנָנִי (Janani) es una forma abreviada de Hananías, que significa ''el SEÑOR es misericordioso''. Identifica al menos a cinco individuos distintos. El vidente Hanani reprendió al rey Asá de Judá por confiar en Aram en lugar del SEÑOR (2 Cr 16:7) y fue encarcelado por ello, un ejemplo poderoso de audacia profética frente a la hostilidad real. Su hijo Jehú ben Hanani profetizó contra Baasa de Israel (1 R 16:1, 7) y después contra Josafat (2 Cr 19:2; 20:34). Un músico levita llamado Hanani sirvió en el coro del templo de David (1 Cr 25:4, 25). El hermano de Nehemías, Hanani, trajo noticias del estado ruinoso de Jerusalén (Neh 1:2) y luego fue nombrado cogobernador de la ciudad (Neh 7:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2608a', 'spa', 'Hananías; nombre teofórico que significa ''YHWH ha sido clemente'', llevado por múltiples personajes bíblicos.', 'Hananías; nombre teofórico que significa ''YHWH ha sido clemente'', llevado por múltiples personajes bíblicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2610', 'spa', 'Ser contaminado o profanado (Qal); profanar o contaminar (Hifil); corromper mediante adulación o hipocresía', 'Construido a partir de una raíz que evoca el apartarse de lo recto, este verbo describe la contaminación moral y ritual en varios niveles. En el Qal, la tierra misma ''queda profanada'' por derramamiento de sangre (Sal 106:38), por idolatría equiparada al adulterio (Jer 3:1, 9) o por la violación del pacto que contamina toda la tierra (Is 24:5). El Hifil causativo intensifica la acción: no contaminaréis la tierra con sangre (Nm 35:33), y la infidelidad de Judá ha profanado el campo (Jer 3:2). Daniel 11:32 introduce un tercer sentido notable: corromper a las personas mediante lisonjas engañosas, donde el matiz relacional e insidioso de esta profanación se hace patente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2611', 'spa', 'Impío, profano, hipócrita — aquel cuya piedad exterior enmascara corrupción moral interior y desafío a Dios.', 'Un término agudo de censura moral que marca a una persona como profana e impía. Concentrado en la literatura sapiencial — solo Job acumula ocho ocurrencias —, designa a quien cuya religiosidad es un barniz sobre una profunda corrupción. Job 8:13 declara que ''la esperanza del impío perecerá'', mientras que Isaías 9:16 y 10:6 extienden la acusación a naciones enteras. Curiosamente, el cognado árabe ḥanīf pasó a significar ''quien se inclina a la verdadera religión'', un sentido casi opuesto. En español se traduce como ''hipócrita'' o ''impío'', captando las dimensiones de falsedad y profanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2617a', 'spa', 'Fidelidad pactual, amor leal, misericordia, bondad; el amor fiel de Dios hacia su pueblo y la bondad entre personas.', 'חֶסֶד es posiblemente el sustantivo de mayor peso teológico en la Biblia hebrea, y uno de los más difíciles de traducir a una sola palabra. Su campo semántico se extiende desde el compromiso inquebrantable de Dios con Israel hasta los actos interpersonales de bondad leal, pasando por la tierna misericordia y compasión. La dificultad se refleja en cómo las lenguas luchan con el término: el árabe divide entre raḥma («misericordia») y wafāʾ («lealtad»); el coreano alterna entre 인자하심 y 사랑; el español oscila entre misericordia, bondad y lealtad. Ninguna traducción individual abarca el conjunto. La fuerza de esta palabra radica precisamente en esa fusión: el amor de Dios es fiel, su fidelidad es bondadosa, y su bondad está comprometida en el pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2618', 'spa', 'nombre propio que significa «hijo de misericordia»; oficial de Salomón', 'Este nombre propio teofórico aparece en 1 Reyes 4:10 como uno de los doce gobernadores de distrito de Salomón, responsables de abastecer la casa real. El nombre significa literalmente «hijo de misericordia» o «hijo de jésed», encarnando el concepto hebreo de lealtad pactual y bondad. Tales nombres en el antiguo Israel reflejaban con frecuencia la piedad de los padres o sus aspiraciones para el carácter del hijo, y el elemento jésed se conecta con una de las palabras teológicamente más ricas de la Escritura hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2620', 'spa', 'Refugiarse, buscar amparo: usado predominantemente para expresar confianza en Dios como lugar protector de refugio', 'Refugiarse, buscar amparo: usado predominantemente para expresar confianza en Dios como lugar protector de refugio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2621', 'spa', 'Hosa; (1) portero levita en tiempos de David; (2) ciudad en el territorio de Aser', 'Hosa (חֹסָה) funciona como nombre propio tanto personal como geográfico, derivado de la raíz que significa «refugio» o «buscar amparo». Como persona, Hosa fue uno de los porteros levitas designados por David para el servicio del templo (1 Cr 16:38; 26:10, 11, 16), encargado de custodiar la puerta occidental. Como lugar, Hosa aparece en la descripción de los límites de la heredad tribal de Aser (Jos 19:29), aunque su ubicación exacta permanece sin identificar. Las lecturas de la Septuaginta varían considerablemente (Ἰασίφ, Σουσά, Ὠσά), lo que sugiere una incertidumbre temprana respecto al topónimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2623', 'spa', 'Fiel, piadoso, devoto: quien practica la lealtad de pacto (חֶסֶד); dicho de Dios: misericordioso y clemente', 'Fiel, piadoso, devoto: quien practica la lealtad de pacto (חֶסֶד); dicho de Dios: misericordioso y clemente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2624', 'spa', 'La cigüeña; ave zancuda migratoria de gran tamaño, nombrada a partir de la raíz que significa ''fiel, leal'' por su crianza devota.', 'El sustantivo femenino chasidah designa la cigüeña, etimológicamente derivado de chesed (''amor leal''), reflejando la observación antigua del cuidado devoto de esta ave hacia sus crías. Aparece entre las aves impuras en las leyes alimentarias (Lev 11:19; Deut 14:18). En Jeremías 8:7 se presenta como criatura de migración estacional confiable, avergonzando a Israel que no conoce los tiempos señalados. En el Salmo 104:17 anida en los cipreses, y en Zacarías 5:9 dos mujeres con alas semejantes a las de la cigüeña llevan lejos el efa de maldad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2625', 'spa', 'Una especie de langosta (colectivo), asociada consistentemente con la devastación agrícola y el juicio divino.', 'El sustantivo masculino chasil designa un tipo específico de langosta, siempre colectivo y siempre destructivo. Aparece exclusivamente en contextos de plaga agrícola y juicio divino: las plagas de langostas de Joel 1:4 y 2:25, las maldiciones del pacto en 1 Reyes 8:37 y 2 Crónicas 6:28, y la recolección de botín ''como recolección del chasil'' en Isaías 33:4. La especie exacta sigue siendo debatida, pero el término aparece siempre en paralelo con arbeh (la langosta común) y yeleq (la langosta rastrera), sugiriendo una etapa o variedad particular dentro de la familia de las langostas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2633', 'spa', 'riqueza, tesoro, bienes acumulados; en sentido figurado, abundancia de provision divina', 'El termino hebreo חֹסֶן designa riqueza acumulada y tesoros almacenados, empleado tanto para bienes materiales como para las provisiones salvificas de Dios. Proverbios 15:6 contrasta el ''gran tesoro'' en la casa del justo con la turbacion que acompana los ingresos del impío. Jeremias 20:5 lo aplica concretamente a las riquezas saqueadas de Jerusalen. De modo notable, Isaias 33:6 transforma el concepto en abundancia espiritual: ''riqueza de salvaciones, sabiduria y conocimiento.'' El arco semantico va de lo material a lo espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2635', 'spa', 'Barro, arcilla; sustantivo arameo para material cerámico, usado exclusivamente en la visión de la estatua de Nabucodonosor (Dn 2).', 'Este sustantivo arameo designa el barro o material cerámico y aparece exclusivamente en Daniel capítulo 2, donde describe los pies y los dedos de la gran estatua de Nabucodonosor: parte de hierro, parte de barro. La mezcla de hierro fuerte con barro frágil se convierte en la imagen clave del profeta para un reino dividido que no puede mantenerse unido (Dn 2:41-43). La palabra tiene cognados en diversas lenguas semíticas: el siríaco para «tiesto», el asirio para «vasija de barro» e incluso el árabe para «alfarería», mostrando lo fundamental que era este material en la vida del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2637', 'spa', 'Carecer, estar en necesidad, disminuir; en Hifil, causar carencia o privar; en Piel, hacer inferior o despojar.', 'Carecer, estar en necesidad, disminuir; en Hifil, causar carencia o privar; en Piel, hacer inferior o despojar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2638', 'spa', 'Falto, carente, deficiente: quien está sin algo esencial, especialmente juicio o entendimiento. חָסֵר describe a una persona o cosa que es deficiente ', 'Falto, carente, deficiente: quien está sin algo esencial, especialmente juicio o entendimiento. חָסֵר describe a una persona o cosa que es deficiente o carente. Su uso bíblico más distintivo es la construcción de Proverbios חֲסַר־לֵב, ''falto de corazón'', es decir, desprovisto de juicio, sensatez o discernimiento moral. Esta frase aparece casi una docena de veces en Proverbios para caracterizar al necio que cae en adulterio (6:32), al joven ingenuo que se adentra en la tentación (7:7) y al perezoso cuyo campo está cubierto de maleza (24:30). Fuera de Proverbios, David pregunta a Aquis ''¿acaso me faltan locos?'' (1 S 21:15), y Eclesiastés 6:2 describe a un hombre al que nada le falta pero no puede disfrutarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2640', 'spa', 'carencia, falta, escasez total de lo necesario', 'Sustantivo que expresa carencia o deficiencia, apareciendo en contextos de privación severa. Deuteronomio lo emplea dos veces para describir las condiciones extremas de la guerra de asedio, cuando la gente carece de todo lo necesario para sobrevivir. Amós lo utiliza en la expresión impactante ''limpieza de dientes'', que significa hambruna: la falta de alimento que manche los dientes. El término enfatiza no una simple escasez, sino la ausencia total de necesidades básicas, describiendo condiciones de necesidad desesperada y privación absoluta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2645', 'spa', 'Cubrir (la cabeza, en duelo o vergüenza); revestir o recubrir (una superficie con oro o madera)', 'El verbo חָפָה (jafah) significa ''cubrir'', y sus dos acepciones principales se distinguen por la conjugación verbal. En el Qal, describe el acto de cubrirse la cabeza como expresión de duelo, vergüenza o condena: David subiendo al Monte de los Olivos descalzo y con la cabeza cubierta (2 S 15:30), agricultores cubriéndose la cabeza durante la sequía (Jer 14:3-4), y Amán llevado con la cabeza cubierta tras su caída (Est 6:12; 7:8). En el Piel (intensivo), el término se traslada al ámbito constructivo: revestir o recubrir superficies con oro, como en el relato detallado del Cronista sobre el templo de Salomón, donde paredes, vigas y el Lugar Santísimo son recubiertos de oro fino (2 Cr 3:5-9). El participio Nifal aparece una sola vez describiendo las alas de una paloma cubiertas de plata (Sal 68:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2646', 'spa', 'dosel, cámara nupcial (espacio íntimo de cobertura y protección)', 'Cobertura o cámara cerrada, usada tanto literal como metafóricamente. Isaías describe un dosel protector sobre la gloria de Sion, mientras que los Salmos y Joel lo emplean para referirse a la cámara del novio o de la novia. El término enfatiza tanto la cobertura (protección desde arriba) como el recinto (espacio privado e íntimo). En contextos nupciales, se refiere a la cámara especial donde los novios celebran su unión. La imagen combina ideas de refugio, privacidad, honor y celebración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2648', 'spa', 'Apresurarse, darse prisa; también huir con alarma o pánico, sobresaltarse o agitarse por el miedo', 'Un verbo que abarca desde la prisa deliberada hasta el pánico provocado por el terror. En su extremo más suave, describe a la nodriza de Mefiboset apresurándose a huir con el niño (2 S 4:4) y a los arameos abandonando sus pertenencias en su carrera por escapar (2 R 7:15). En su extremo más intenso, capta la alarma pura: el clamor del salmista ''en mi angustia dije: cortado soy'' (Sal 31:23; 116:11), los reyes que ven a Sion y ''huyen aterrados'' (Sal 48:5), y las aguas que ''se retiran'' ante la reprensión de Dios (Sal 104:7). Incluso el behemot de Job 40:23 se describe como imperturbable cuando el Jordán crece, una negación deliberada de la connotación de pánico de este verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2649', 'spa', 'prisa, huida apresurada, apremio temeroso', 'Prisa urgente o huida apresurada, frecuentemente acompañada de temor o sobresalto. El término aparece en contextos de partida precipitada, ya sea huyendo del peligro o actuando bajo presión. Éxodo lo emplea para describir la salida acelerada de Israel de Egipto, cuando debían comer la Pascua listos para partir de inmediato. Deuteronomio lo vincula con el pan de aflicción, recordando a Israel su escape apresurado. Isaías contrasta el futuro éxodo de Israel con la partida de Egipto, prometiendo que no saldrán con prisa ni con pánico. El término captura tanto la velocidad como la urgencia emocional que la impulsa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2650', 'spa', 'Hupim: hijo o descendiente de Benjamín', 'Nombre benjaminita que aparece en listas genealógicas con cierta variación textual. El nombre figura en Génesis entre quienes descendieron a Egipto con Jacob, y en Crónicas dentro de contextos genealógicos más complejos. Existe confusión en la tradición textual entre Hupim, Hufam y nombres afines, lo cual sugiere variantes textuales o bien múltiples individuos con nombres similares dentro del linaje de Benjamín. La complejidad genealógica refleja los desafíos de preservar registros tribales a lo largo de generaciones y a través de diversas transmisiones textuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2651', 'spa', 'El hueco de las manos ahuecadas; siempre en dual, denotando ambas manos juntas como recipiente para sostener o recoger.', 'El sustantivo chophen aparece únicamente en la forma dual chophnayim, evocando la imagen de dos manos ahuecadas juntas formando un recipiente natural. Moisés y Aarón llenan sus chophnayim con hollín de horno para lanzarlo hacia el cielo, provocando úlceras sobre Egipto (Ex 9:8). El sumo sacerdote toma un chophnayim lleno de incienso para entrar al Lugar Santísimo en el Día de la Expiación (Lev 16:12). El enigma de Agur pregunta quién ha recogido el viento en sus puños (Prov 30:4), y Qohélet declara que un puñado con quietud supera a dos puñados con fatiga (Ecl 4:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2652', 'spa', 'Jofni; hijo de Eli el sacerdote, cuya corrupcion en Silo provoco el juicio divino', 'Jofni fue uno de los dos hijos de Eli que servian como sacerdotes en Silo, pero abusaron notoriamente de su oficio. Su historia en 1 Samuel es un relato de corrupcion sacerdotal confrontada por el juicio divino: tomaban la carne de los sacrificios por la fuerza y trataban la ofrenda del Senor con desprecio. La profecia de que ambos, Jofni y Finees, moririan el mismo dia (1 S 2:34) se cumplio en la batalla de Afec, cuando los filisteos capturaron el arca (1 S 4:11, 17). El nombre podria estar relacionado con el sabeo hpn. La Septuaginta lo transcribe como Ofni.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2654a', 'spa', 'חָפֵץ capta una atracción cálida y comprometida — no mera aprobación intelectual, sino placer sentido y deseo activo. Cuando Dios se deleita en alguie', 'חָפֵץ capta una atracción cálida y comprometida — no mera aprobación intelectual, sino placer sentido y deseo activo. Cuando Dios se deleita en alguien, señala un favor y una aceptación profundos (Nm 14:8; 2 S 22:20); cuando una persona se deleita en los mandamientos de Dios, transforma la obediencia de deber en gozo (Sal 112:1; 119:35). El verbo también posee un matiz volitivo: ''Si el SEÑOR quisiere'' (Jue 13:23) y la negativa del pariente redentor a actuar (Rt 4:6; Dt 25:7-8). Las traducciones al español se dividen entre el lenguaje del placer y el del deseo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2655', 'spa', 'Que se deleita en, dispuesto, deseoso — adjetivo verbal que describe a quien se complace en algo o se inclina hacia ello', 'El adjetivo חָפֵץ (jafets) describe a alguien que se deleita en algo, lo desea o está dispuesto a ello: una persona cuya disposición interior la inclina hacia algo. Aparece tanto en contextos positivos como negativos. David dice a Salomón que Dios busca un corazón ''dispuesto'' (חָפֵץ) a buscarlo (1 Cr 28:9). El salmista pregunta ''¿quién es el que se deleita en la vida?'' (Sal 34:13) y declara que Dios no se complace en la maldad (Sal 5:5). El Salmo 35:27 habla de quienes ''se deleitan en'' la vindicación del justo. El término también cubre la simple disposición: Jeroboam consagró como sacerdotes a ''quien estuviera dispuesto'' (1 R 13:33), y la viña de Nabot se ofrece ''si estás dispuesto'' (1 R 21:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2656', 'spa', 'Deleite, placer, deseo, voluntad; también un asunto o negocio; por extensión, un objeto precioso o deseable', 'Deleite, placer, deseo, voluntad; también un asunto o negocio; por extensión, un objeto precioso o deseable');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2657', 'spa', 'Hefzi-bá («mi deleite está en ella»), nombre de la madre de Manasés y nombre simbólico de Sion restaurada', 'Nombre femenino compuesto de חֵפֶץ («deleite») y בָּהּ («en ella»), usado tanto como nombre personal como epíteto profético. En 2 Reyes 21:1, Hefzi-bá es la madre del rey Manasés. En Isaías 62:4, el nombre se aplica simbólicamente a Sion: «No te llamarán más Desamparada... sino Hefzi-bá, porque el SEÑOR se deleita en ti.» Las traducciones multilingües reflejan la tensión entre transliterar el nombre y traducir su significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2658', 'spa', 'Cavar en la tierra (pozos, fosas); por extensión, explorar, escudriñar o buscar con afán como quien excava en busca de un tesoro oculto.', 'Cavar en la tierra (pozos, fosas); por extensión, explorar, escudriñar o buscar con afán como quien excava en busca de un tesoro oculto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2659', 'spa', 'Avergonzarse, ser confundido o humillado (Qal); causar vergüenza o traer deshonra sobre alguien (Hifil). Verbo cuyo Qal expresa la experiencia intrans', 'Avergonzarse, ser confundido o humillado (Qal); causar vergüenza o traer deshonra sobre alguien (Hifil). Verbo cuyo Qal expresa la experiencia intransitiva de vergüenza y humillación, mientras que su Hifil dirige la acción hacia afuera, causando deshonra a otra persona. En el Qal, casi siempre aparece junto a בּוֹשׁ (''avergonzarse''), formando un poderoso hendíadis de desgracia total (Sal 35:4, 26; 71:24; Is 24:23; Mi 3:7). En el Hifil, Proverbios lo emplea para la deshonra social concreta: un hijo que avergüenza a sus padres (Pr 19:26) o una persona malvada que actúa vergonzosamente (Pr 13:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2660a', 'spa', 'Héfer, nombre propio masculino de un jefe de clan manasita, un judahíta y uno de los guerreros de David', 'Héfer (a veces transliterado Jéfer) es un nombre propio que aparece en varios contextos genealógicos y militares. Como descendiente manasita de Galaad, Héfer fue padre de Zelofehad, cuyas hijas peticionaron célebremente por derechos de herencia (Núm 26:32-33; 27:1; Jos 17:2-3). El nombre también pertenece a un hijo de Asur en la genealogía de Judá (1 Cr 4:6) y posiblemente a uno de los valientes de David (1 Cr 11:36), aunque ese texto es disputado. La Septuaginta lo traduce como Opher o Aphar, reflejando diversas tradiciones de transliteración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2664', 'spa', 'Buscar, escudriñar, investigar; en Hitpael, disfrazarse; en voz pasiva, ser escudriñado o expuesto.', 'Buscar, escudriñar, investigar; en Hitpael, disfrazarse; en voz pasiva, ser escudriñado o expuesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2669', 'spa', 'libertad, separación (especialmente para cuarentena o aislamiento)', 'Término difícil que aparece únicamente en la expresión «casa de libertad» o «casa de separación», refiriéndose a una morada apartada donde el rey Uzías vivió tras ser afectado por la lepra. El término sugiere o bien liberación de responsabilidades habituales, o bien separación de la comunidad con fines de cuarentena. La mayoría de los intérpretes lo entienden como una casa aislada donde el rey leproso fue confinado, apartado del templo y de sus funciones reales. La expresión captura la doble realidad del aislamiento forzado: exento de deberes pero prisionero por la enfermedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2670', 'spa', 'Libre, liberado: suelto de la esclavitud u obligación, puesto en libertad. חׇפְשִׁי es un adjetivo que significa ''libre'', usado principalmente en los ', 'Libre, liberado: suelto de la esclavitud u obligación, puesto en libertad. חׇפְשִׁי es un adjetivo que significa ''libre'', usado principalmente en los códigos legales que regulan la manumisión de esclavos hebreos. Su uso más concentrado aparece en el Código de la Alianza (Éx 21:2, 5, 26-27), donde un siervo hebreo sale חׇפְשִׁי después de seis años de servicio, y en la legislación deuteronómica paralela (Dt 15:12-13, 18). Jeremías 34:9-16 registra el dramático episodio en que los oficiales de Sedequías proclamaron libertad para sus esclavos hebreos y luego se retractaron. Isaías 58:6 amplía el término más allá de la esclavitud: ''dejar ir libres a los oprimidos'' es la esencia del ayuno que Dios desea. En Job 3:19, la palabra adquiere un matiz existencial conmovedor: en el Seol, ''el esclavo es libre de su señor''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2671', 'spa', 'Flecha — proyectil puntiagudo disparado con arco, usado como arma de guerra y como figura del juicio divino', 'Flecha — proyectil puntiagudo disparado con arco, usado como arma de guerra y como figura del juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2672', 'spa', 'Labrar, cortar, cantear piedra; de canteros como artesanos, cisternas y roca labradas, hendidura figurativa del rayo.', 'Labrar, cortar, cantear piedra; de canteros como artesanos, cisternas y roca labradas, hendidura figurativa del rayo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2673', 'spa', 'Dividir, partir por la mitad; en Qal, repartir activamente; en Nifal, ser dividido; idiomáticamente, acortar los días.', 'Un verbo de partición y división que va desde la economía ganadera hasta el destino profético. Tras luchar en Peniel, Jacob divide su campamento en dos compañías (Gn 32:7; 33:1). La ley prescribe dividir el precio de un buey muerto (Éx 21:35). Moisés reparte el botín de guerra (Nm 31:27, 42). Elías y Eliseo golpean el Jordán y sus aguas ''se dividen'' (2 R 2:8, 14). El Nifal pasivo aparece también en profecía: Ezequiel promete que el reino ''no se dividirá en dos'' de nuevo (Ez 37:22). De modo más conmovedor, el salmista advierte que los hombres sanguinarios y tramposos ''no vivirán la mitad de sus días'' (Sal 55:23), una extensión idiomática donde dividir se aplica al lapso de la vida misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2674', 'spa', 'Hazor: importante ciudad real cananea en el norte de Israel, además de varios asentamientos menores del mismo nombre. חָצוֹר designa principalmente la', 'Hazor: importante ciudad real cananea en el norte de Israel, además de varios asentamientos menores del mismo nombre. חָצוֹר designa principalmente la gran ciudad real cananea en la Alta Galilea, uno de los centros urbanos más importantes de la Edad del Bronce en el antiguo Cercano Oriente. En la narrativa de la conquista, Hazor es señalada como ''la cabeza de todos aquellos reinos'' bajo el rey Jabín, a quien Josué derrotó y cuya ciudad quemó, la única ciudad cananea que se dice explícitamente fue destruida por fuego (Jos 11:1, 10-11, 13). El nombre reaparece en Jueces 4:2, 17, donde un segundo Jabín, rey de Hazor, oprime a Israel. Salomón más tarde fortificó Hazor junto con Meguido y Gezer (1 R 9:15), y los asirios la capturaron en 733 a.C. (2 R 15:29). Jeremías 49:28-33 se dirige a ''los reinos de Hazor'' como localidad árabe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2676', 'spa', 'medianoche, mitad de la noche', 'El punto medio de la noche, la medianoche. El término se forma a partir de la raíz que significa «dividir» o «cortar por la mitad», designando así el momento que parte la noche en dos mitades. Éxodo lo emplea para señalar el instante preciso en que Dios hirió a los primogénitos de Egipto durante la décima plaga. Job y Salmos lo utilizan para referirse a la hora más profunda y oscura de la noche, cuando ocurren sucesos repentinos o cuando los fieles se levantan a alabar a Dios. La medianoche funciona tanto como marcador temporal como símbolo de oscuridad profunda o vigilancia urgente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2677', 'spa', 'Mitad, una de dos partes iguales; también el medio o punto central de una extensión espacial o temporal.', 'Un término cuantitativo corriente que divide algo en dos porciones iguales: la mitad de una tribu, medio codo, la mitad del botín. Rige medidas precisas en los planos del tabernáculo (Éx 25:10, 17) y la repartición de la tierra entre las tribus (Jos 13:29). Sin embargo, en un puñado de pasajes vívidos pasa de fracción a punto focal: «a medianoche» (Éx 12:29), «a la mitad de la noche» (Rt 3:8) o «en medio del Jordán» (Jos 4:10), donde lenguas como el español con medianoche y el alemán con Mitte confirman la lectura de centro espacial y no de mitad numérica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2678', 'spa', 'Flecha o flechas — proyectil disparado con arco, usado literalmente y como metáfora del juicio divino.', 'Una forma variante del más común חֵץ (''flecha''), este sustantivo aparece tanto en contextos literales como figurados. Su mayor concentración está en la dramática narrativa de 1 Samuel 20, donde las flechas de Jonatán sirven como señal encubierta para David — un episodio donde el objeto físico porta un enorme peso narrativo. En otros pasajes aparece en contextos bélicos (2 R 9:24; 13:15-18) y metafóricamente como la mano aflictiva de Dios (Sal 38:2; Job 6:4). En español se traduce uniformemente como ''flecha'', confirmando el sentido concreto del arma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2682a', 'spa', 'Hierba, forraje, vegetación verde: crecimiento vegetal usado como pasto y como imagen bíblica de la transitoriedad humana. חָצִיר se refiere a la hier', 'Hierba, forraje, vegetación verde: crecimiento vegetal usado como pasto y como imagen bíblica de la transitoriedad humana. חָצִיר se refiere a la hierba verde o vegetación, el tipo de crecimiento exuberante que brota rápidamente y se marchita con igual rapidez. Cumple una doble función en las Escrituras: en lo práctico, es forraje para el ganado (1 R 18:5; Sal 104:14; 147:8), y en Números 11:5 puede designar puerros, un cultivo verde específico que los israelitas anhelaban en el desierto. Teológicamente, se convirtió en una de las metáforas más poderosas de la Biblia para la fragilidad humana: ''toda carne es hierba'' (Is 40:6-8), eco que resuena en Salmo 103:15 y Santiago 1:10-11. La ''hierba de los terrados'' (Sal 129:6; 2 R 19:26) que se seca antes de poder arrancarse retrata a los enemigos como efímeros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2687', 'spa', 'grava, piedrecillas (usado figuradamente para expresar penalidad)', 'Piedrecillas o grava, que aparece únicamente en contextos figurados que expresan penalidad o decepción. Proverbios lo emplea metafóricamente para las amargas consecuencias de la mentira: tener la boca llena de grava en lugar de la dulzura esperada. Lamentaciones usa la imagen de dientes quebrados con cascajo para describir el trato severo de Dios durante la destrucción de Jerusalén. El término evoca incomodidad, desengaño y la dolorosa realidad oculta tras apariencias engañosas. La grava en la boca representa lo áspero, indigerible y doloroso, en contraste con lo que debería satisfacer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2689', 'spa', 'Trompeta de plata (חֲצֹצְרָה), un clarín de metal batido usado para la asamblea, la guerra y el culto en el templo.', 'Trompeta de plata (חֲצֹצְרָה), un clarín de metal batido usado para la asamblea, la guerra y el culto en el templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2690', 'spa', 'chatsotser — tocar trompetas; verbo denominativo para hacer sonar clarines de plata en el culto levítico', 'El verbo denominativo chatsotser (derivado de chatsotsrah, ''trompeta de plata'') describe el acto de hacer sonar trompetas en el culto levítico organizado y las ceremonias del templo. Las doce apariciones se encuentran exclusivamente en Crónicas, donde el Cronista retrata el orden litúrgico de la época del Segundo Templo: los trompeteros acompañan la procesión del arca hacia Jerusalén (1 Cr 15:24), la dedicación del Templo de Salomón (2 Cr 5:12-13), el festival sacrificial de Salomón (2 Cr 7:6), la línea de batalla de Abías (2 Cr 13:14) y las ofrendas de la reforma de Ezequías (2 Cr 29:28). Las variantes Ketiv/Qere y las formas participiales (mechatserim, ''trompeteros'') representan variación ortográfica y morfológica, no sentidos distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2691a', 'spa', 'Espacio abierto cercado: atrio de templo, palacio o casa; raramente aldea o asentamiento sin muralla.', 'Enraizado en la idea de cercamiento, este sustantivo designa con mayor frecuencia los espacios abiertos que rodean los edificios sagrados y reales de Israel: los atrios del tabernáculo (Éx 27:9ss.), del templo (Sal 84:11; 96:8) y de los palacios reales (1 Re 7:8). La evidencia multilingüe es notablemente uniforme: inglés court/courtyard, español atrio, francés parvis, alemán Vorhof apuntan a la misma realidad arquitectónica. En dos raras apariciones (1 Cr 4:32-33), la palabra pasa a significar asentamientos o aldeas sin muralla, donde español aldeas y la forma plural señalan una extensión semántica distinta, del espacio cerrado a la habitación abierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2691b', 'spa', 'Aldeas, caseríos — poblados sin muralla o localidades dependientes que rodean una ciudad principal', 'Aldeas, caseríos — poblados sin muralla o localidades dependientes que rodean una ciudad principal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2695', 'spa', 'Jetsro: uno de los valientes guerreros de David', 'Uno de los guerreros de elite de David, identificado como «el carmelita» (de Carmel en Judá, no del monte Carmelo). Su nombre aparece en las listas de los valientes de David, con variaciones textuales entre Samuel y Crónicas. Las diferencias ketiv/qeré (Jetsro/Jetsrai) reflejan incertidumbres escribales en la transmisión, fenómeno común en las listas de guerreros de 2 Samuel 23 y 1 Crónicas 11. Estos valientes formaban el núcleo del liderazgo militar de David, destacándose por su valentía y lealtad excepcionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2696', 'spa', 'Hezrón: hijo de Rubén, nieto de Judá y ancestro de David, y un lugar en el sur de Judá. חֶצְרוֹן es un nombre propio con referentes tanto personales c', 'Hezrón: hijo de Rubén, nieto de Judá y ancestro de David, y un lugar en el sur de Judá. חֶצְרוֹן es un nombre propio con referentes tanto personales como geográficos, que aparece 18 veces en la Biblia hebrea. El nombre probablemente deriva de חָצֵר (''recinto, patio''). Como nombre personal, pertenece a dos individuos distintos: primero, un hijo de Rubén que descendió a Egipto con la casa de Jacob (Gn 46:9; Éx 6:14; Nm 26:6; 1 Cr 5:3). Segundo, y mucho más prominente, un hijo de Fares y nieto de Judá, a través del cual desciende la línea real davídica (Gn 46:12; Nm 26:21; Rt 4:18-19; 1 Cr 2:5, 9, 18, 21, 24-25; 4:1). Como topónimo, Hezrón aparece en la frontera sur de Judá (Jos 15:3, 25; Nm 34:4), a veces compuesto como Queriot-Hezrón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2698', 'spa', 'Hazerot; un campamento de Israel en el desierto durante el éxodo, que significa ''recintos'' o ''atrios''.', 'Chatseroth es un nombre propio de lugar que designa uno de los campamentos de Israel en el desierto tras partir del Sinaí. El nombre deriva de chatser (''recinto, atrio''), sugiriendo quizás un sitio con formaciones rocosas naturales a modo de cercados. Se recuerda especialmente como el lugar donde Miriam y Aarón desafiaron la autoridad de Moisés y Miriam fue herida con una enfermedad cutánea (Núm 12). Los registros de itinerario en Números 11:35 y 33:17-18 documentan la llegada y la partida, mientras que Deuteronomio 1:1 lo menciona entre los puntos de referencia que enmarcan el discurso final de Moisés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2704', 'spa', 'Hazar-enán (''aldea de las fuentes''), lugar en el límite noreste de la tierra prometida', 'Topónimo compuesto de חָצֵר (''recinto, aldea'') y עֵינָן (''fuentes, manantiales''), que designa un asentamiento en el extremo noreste ideal de Canaán. Aparece en la descripción mosaica de las fronteras (Nm 34:9-10) y en la distribución visionaria de la tierra en Ezequiel (Ez 47:17; 48:1), marcando en ambos casos el punto donde la frontera norte gira hacia el oriente. Su presencia constante en textos tan distantes entre sí subraya su función como referencia geográfica fija en la concepción territorial de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2705', 'spa', 'Hazar-sual (''aldea del chacal/zorro''), pueblo en el sur de Judá asignado también a Simeón', 'Topónimo compuesto de חָצֵר (''recinto, aldea'') y שׁוּעָל (''zorro, chacal''), que identifica un asentamiento en la región del Neguev. Figura en las listas de ciudades del sur de Judá (Jos 15:28), de Simeón (Jos 19:3), en el registro genealógico del Cronista (1 Cr 4:28) y entre los lugares repoblados tras el exilio (Neh 11:27). Su doble asignación a Judá y a Simeón refleja la superposición de territorios tribales en el extremo meridional de la tierra.');